/* Textes prêts à lire — 10 par exercice (by Stephen) */
(function(){var D=window.AO_DATA;D.exerciseTexts={"mot":[{"t":"Confiance","x":["La confiance, c’est un crédit qu’on s’ouvre à soi-même avant de l’ouvrir aux autres.","On la reconnaît à un détail : on arrête de vérifier trois fois la porte.","Quand mon voisin m’a laissé les clés de son appartement pour arroser ses plantes, il ne m’a pas fait signer de papier. Il m’a juste dit « à jeudi ».","Chez moi, la confiance a eu la taille d’un trousseau : petit, lourd, et plus précieux qu’il n’en a l’air.","Depuis, je me demande à qui j’ai donné mes clés, et à qui je devrais en rendre."]},{"t":"Héritage","x":["Un héritage, ce n’est pas ce qu’on reçoit : c’est ce qu’on décide d’entretenir.","Ma grand-mère m’a laissé une casserole bosselée. Pas d’argent, pas de terrain : une casserole.","Dedans, elle a fait mijoter cinquante ans de dimanches.","Je ne l’ai pas rangée : je m’en sers. Parce qu’un héritage qu’on n’utilise pas devient un meuble, et qu’un héritage qu’on utilise devient une façon de vivre.","Alors ma question n’est pas « qu’ai-je reçu ? » mais « qu’est-ce que je fais mijoter ? »"]},{"t":"Rareté","x":["Ce qui est rare n’est pas toujours précieux, mais ce qui est précieux a presque toujours été rare à un moment.","Prenez le temps. Il n’y en a pas dans les magasins.","Un matin de décembre, j’ai passé une heure entière sans téléphone, assis devant une tasse de thé. Personne ne m’a écrit, rien n’a brûlé.","Cette heure-là m’a coûté plus cher que n’importe quel achat : elle m’a coûté mon habitude.","Depuis, je protège une heure par semaine comme on protège une pièce rare."]},{"t":"Patience","x":["La patience, ce n’est pas attendre : c’est continuer pendant que ça ne se voit pas.","Quand j’ai commencé la guitare, mes doigts saignaient et mon voisin soupirait.","Pendant trois mois, j’ai joué le même accord. Un seul.","Au quatrième mois, un autre accord est arrivé, comme un invité qui frappe à la porte sans prévenir.","Depuis, je vois la patience comme une graine : on n’entend pas pousser, mais un jour la fenêtre est pleine de vert."]},{"t":"Frontière","x":["Une frontière n’est pas un mur : c’est un endroit où l’on se présente.","À dix-huit ans, j’ai traversé une frontière avec un sac et une adresse écrite sur un papier plié. Le douanier m’a regardé trois secondes.","Ces trois secondes m’ont appris qu’une frontière sépare, mais qu’elle sert surtout à dire : « voilà qui je suis, voilà d’où je viens ».","Aujourd’hui, quand je pose une limite à quelqu’un, je me rappelle le douanier : je ne ferme pas la porte, je dis où elle commence."]},{"t":"Lenteur","x":["La lenteur a mauvaise presse. On lui préfère la vitesse, qui a de meilleurs publicitaires.","Pourtant, c’est en marchant lentement que j’ai vu, pour la première fois, la fleur sur le muret de ma rue.","Elle était là depuis des années. Moi, je courais.","La lenteur n’est pas un retard : c’est une loupe.","Alors si on vous demande de ralentir, ne vous excusez pas. Répondez simplement : « je regarde. »"]},{"t":"Élégance","x":["L’élégance, ce n’est pas le luxe : c’est l’absence de bruit inutile.","Un homme a un jour traversé un hall bondé en portant un plateau de verres sans en renverser un seul. Personne n’a applaudi, personne n’a rien remarqué.","C’est précisément ça : l’élégance, c’est quand l’effort disparaît derrière le geste.","Dans mon travail, je cherche la même chose : une phrase si simple qu’on oublie le temps qu’il a fallu pour l’écrire."]},{"t":"Risque","x":["Le risque, c’est la distance entre ce qu’on veut et ce qu’on a déjà.","La première fois que j’ai parlé devant cinquante personnes, j’avais peur de bégayer, de rougir, de disparaître.","J’ai bégayé deux fois, rougi une fois, et je n’ai disparu nulle part.","Voilà ce que le risque m’a appris : on le surévalue avant, on le sous-estime après.","Maintenant je me demande plutôt : et si le vrai risque, c’était de rester à l’abri ?"]},{"t":"Mémoire","x":["La mémoire n’est pas une photo : c’est une recette qu’on réécrit à chaque fois qu’on la cuisine.","Je me souviens de l’odeur de la cuisine de mon enfance, mais plus des murs. Le souvenir a gardé le plus tendre et laissé le reste.","Peut-être est-ce une bonne nouvelle : on garde ce qui nous a nourris.","Alors quand je raconte un souvenir, j’essaie de ne pas dire seulement ce qui s’est passé, mais ce qui est resté."]},{"t":"Silence","x":["Le silence n’est pas l’absence de parole : c’est la parole qui écoute.","Dans une réunion, un collègue s’est tu pendant dix secondes avant de répondre. Dix secondes, c’est un siècle. Tout le monde a retenu son souffle.","Et sa réponse, la seule de la matinée, a changé la décision.","Depuis, je ne cherche plus à remplir les blancs : je les prépare.","Parce qu’un silence bien placé est la phrase la plus courte de la langue."]}],"qr":[{"t":"« Pourquoi avez-vous choisi ce projet ? »","x":["Vous me demandez pourquoi j’ai choisi ce projet.","La réponse tient en une raison : j’y ai vu un problème que je rencontrais moi-même.","Chaque semaine, je perdais deux heures à faire à la main ce qu’un outil simple peut faire en dix minutes.","J’ai donc construit cet outil, d’abord pour moi, puis pour d’autres.","En un mot : j’ai choisi ce projet parce qu’il me faisait gagner du temps, et qu’il peut en faire gagner à d’autres."]},{"t":"« Qu’est-ce qui vous distingue des autres candidats ? »","x":["Vous me demandez ce qui me distingue des autres candidats.","Je ne peux pas parler à leur place, mais je peux dire ce que je fais bien : je livre.","Sur mon dernier projet, j’ai tenu le calendrier, alors que la moitié de l’équipe doutait.","Cette régularité, je la cultive depuis des années : un petit pas par jour plutôt qu’un grand soir.","Donc ce qui me distingue, c’est la constance, et je peux vous le prouver sur pièces."]},{"t":"« Pourquoi cette augmentation maintenant ? »","x":["Vous demandez pourquoi cette demande arrive maintenant.","Parce que le contexte a changé : depuis janvier, j’assure en plus la formation des nouveaux arrivants.","Concrètement, j’ai formé six personnes, et leur délai de prise de poste est passé de six à trois semaines.","C’est un gain mesurable pour l’équipe, et c’est un travail que personne ne m’avait demandé au départ.","C’est pour cela que je vous propose d’en parler maintenant, tant que les résultats sont frais."]},{"t":"« Que feriez-vous avec un budget doublé ? »","x":["Vous me demandez ce que je ferais avec un budget doublé.","Je commencerais par sécuriser ce qui marche : deux postes qui portent déjà les résultats.","Ensuite, j’investirais dans un test à petite échelle, avec un critère d’arrêt clair après trois mois.","Je ne promets pas de tout réussir, je promets de mesurer.","Résumé : d’abord consolider, ensuite expérimenter, et toujours rendre des comptes."]},{"t":"« N’est-ce pas trop risqué ? »","x":["Vous demandez si ce choix n’est pas trop risqué.","Oui, il y a un risque, et je préfère le nommer : si le fournisseur retarde, nous perdons deux semaines.","C’est pourquoi j’ai prévu un deuxième fournisseur, déjà contacté, qui peut livrer en cinq jours.","Le risque existe, mais il est borné.","Donc je maintiens ma recommandation, avec ce plan de secours."]},{"t":"« Pourquoi ne pas simplement baisser le prix ? »","x":["Vous demandez pourquoi ne pas simplement baisser le prix.","Parce que le prix ne dit pas seulement combien, il dit aussi quoi : un prix bas attire des clients qui comparent, un prix juste attire des clients qui restent.","Chez nous, 70 % des clients reviennent, justement parce que nous n’avons jamais cédé sur la qualité.","Baisser le prix aujourd’hui serait gagner un client et en perdre trois.","Je préfère donc ajouter de la valeur plutôt que retirer du prix."]},{"t":"« Comment gérez-vous un désaccord dans l’équipe ? »","x":["Vous me demandez comment je gère un désaccord.","Je commence par une règle : chacun reformule la position de l’autre avant de défendre la sienne.","Dans ma dernière équipe, cette règle a transformé une dispute de vingt minutes en une décision de cinq.","Pourquoi ? Parce qu’on se sent écouté avant d’être contredit.","Bref : reformuler d’abord, décider ensuite."]},{"t":"« Quel est votre plus grand défaut ? »","x":["Vous me demandez mon plus grand défaut.","Je veux en faire trop vite : j’aime avancer, et je saute parfois l’étape de relecture.","Cela m’a coûté une erreur de chiffre dans un rapport, que j’ai corrigée le jour même.","Depuis, je me suis imposé une règle : une relecture à froid, vingt minutes après l’écriture.","Un défaut reconnu, c’est déjà un défaut à moitié réglé."]},{"t":"« Pourquoi quitter votre poste actuel ? »","x":["Vous me demandez pourquoi je quitte mon poste actuel.","Je ne le quitte pas par fuite, je le quitte par envie d’élargir : j’ai appris ce que ce poste pouvait m’apprendre.","J’y ai tenu un budget, formé deux personnes et livré trois projets.","Je cherche maintenant un endroit où ces acquis servent à plus grand.","C’est pour cela que votre offre m’intéresse."]},{"t":"« Qu’attendez-vous de nous ? »","x":["Vous me demandez ce que j’attends de vous.","Trois choses simples : des objectifs clairs, un retour régulier, et la possibilité de prendre des responsabilités quand je les mérite.","En échange, je m’engage à livrer, à demander de l’aide tôt, et à ne pas attendre qu’on me relance.","C’est un échange, pas une faveur.","En résumé : de la clarté de votre côté, de la fiabilité du mien."]}],"argumenter":[{"t":"Interdire le téléphone en réunion · 30 s","x":["Je défends une règle simple : pas de téléphone en réunion.","Pourquoi ? Parce qu’un écran allumé, c’est une personne absente.","La dernière fois, j’ai compté quatre regards qui glissaient vers leur poche en dix minutes, et la question a dû être répétée deux fois.","Une réunion sans téléphone, c’est une réunion plus courte. Essayons une semaine."],"d":30},{"t":"Interdire le téléphone en réunion · 1 min","x":["Je défends une règle simple : pas de téléphone en réunion.","Première raison : l’attention ne se partage pas. Quand quelqu’un regarde son écran, il n’entend plus la moitié de ce qui se dit, et il ne s’en rend même pas compte.","Deuxième raison : le message envoyé aux autres. Un téléphone posé sur la table dit « si quelque chose de plus important arrive, je pars ».","[Pause.]","Dans ma dernière réunion de douze personnes, j’ai compté quatre regards vers l’écran en dix minutes, et la même question a été posée deux fois.","On me répondra qu’il y a des urgences. Bien sûr : une personne de garde peut garder son téléphone et le dire.","Pour tous les autres, une heure sans écran, c’est une réunion plus courte et plus claire. Je propose de tester une semaine."],"d":60},{"t":"Interdire le téléphone en réunion · 2 min","x":["Je défends une règle simple : pas de téléphone en réunion.","[Pause.]","Commençons par ce que coûte un écran allumé. Les chercheurs en attention le répètent : on ne fait pas deux choses à la fois, on passe de l’une à l’autre, et chaque passage coûte quelques secondes de concentration. Dans une réunion d’une heure, cela peut représenter plusieurs minutes perdues, pour chaque personne.","Deuxième raison : le message envoyé aux autres. Un téléphone posé face visible sur la table, c’est une phrase silencieuse : « si quelque chose de plus intéressant arrive, je pars ». Ceux qui parlent le sentent, même sans y penser.","Troisième raison : l’efficacité. Dans ma dernière réunion de douze personnes, j’ai compté quatre regards vers l’écran en dix minutes. Résultat : une question posée deux fois, une décision relue trois fois, et dix minutes de plus à la fin.","[Pause.]","On me répondra qu’il existe des urgences, et c’est vrai. Une personne de garde, un parent qui attend un appel de l’école : ces personnes préviennent au début, gardent leur téléphone, et tout le monde comprend.","On me dira aussi que c’est infantilisant. Je réponds que c’est une règle commune, comme l’heure de début : elle protège le temps de tous.","Alors voici ma proposition. Pendant une semaine, les téléphones restent dans la poche ou dans un panier à l’entrée. Au bout de la semaine, nous comparons la durée de nos réunions et le nombre de fois où nous répétons une phrase.","Si rien ne change, nous arrêtons. Si le temps gagné se voit, nous gardons la règle.","Une heure sans écran n’a jamais empêché personne de réussir. Elle aide souvent à être là."],"d":120},{"t":"Apprendre de ses échecs · 30 s","x":["On apprend plus d’un échec que d’une réussite, et je vous le prouve en une histoire.","À mon premier exposé, j’ai lu mes notes sans lever la tête : la salle a décroché.","Au second, j’ai regardé trois personnes : la salle m’a suivi.","L’échec m’a montré exactement où je me trompais. Acceptons d’échouer tôt pour réussir tard."],"d":30},{"t":"Apprendre de ses échecs · 1 min","x":["On apprend plus d’un échec que d’une réussite.","Raison : une réussite cache ses faiblesses. Quand tout marche, on ne sait pas pourquoi. Un échec, lui, montre l’endroit précis où l’on s’est trompé.","[Pause.]","Mon premier exposé : j’ai lu mes notes sans lever la tête, et la salle a décroché au bout de trois minutes. J’ai été vexé, puis j’ai compris : le problème n’était pas mon contenu, c’était mon regard.","Au second exposé, j’ai gardé trois mots sur une carte et j’ai regardé trois personnes. La salle m’a suivi jusqu’au bout.","Je n’aime pas l’échec, mais je le respecte : c’est un professeur franc.","Alors acceptons de rater tôt, petit, souvent, pour réussir tard et grand."],"d":60},{"t":"Apprendre de ses échecs · 2 min","x":["On apprend plus d’un échec que d’une réussite, et je voudrais vous le montrer en trois temps.","[Pause.]","Premier temps : ce que cache la réussite. Quand tout marche, on met cela sur le compte de son talent, ou de la chance, et on ne cherche pas plus loin. On ne sait donc pas ce qu’on a bien fait, on ne peut pas le reproduire.","Deuxième temps : ce que montre l’échec. Il dit précisément où le plan s’est cassé. C’est une information, et les informations précises sont rares.","Troisième temps : une histoire. Mon premier exposé, devant quarante personnes. J’avais tout préparé, sauf une chose : lever la tête. J’ai lu mes notes pendant dix minutes. À la troisième, la salle regardait son téléphone.","[Pause.]","Je suis sorti vexé. Puis je me suis posé une question : qu’est-ce qui a vraiment échoué ? Pas mon contenu, il était bon. C’était ma façon de le dire.","Au second exposé, j’ai gardé trois mots sur une carte, et je me suis fixé une règle : regarder une personne par phrase. La salle m’a suivi, et deux personnes m’ont posé des questions à la fin.","On me dira : « Alors il faut chercher l’échec ? » Non. Il faut simplement ne pas le fuir. Un échec petit, tôt, coûte peu. Un échec grand, tard, coûte cher.","Ma conclusion est simple : faites vos erreurs quand elles sont petites, regardez-les en face, et laissez-les vous apprendre ce que vos réussites ne vous diront jamais."],"d":120},{"t":"Le télétravail, un entraînement · 30 s","x":["Le télétravail n’est pas un confort : c’est un entraînement.","À distance, on doit écrire clairement, planifier, rendre compte. Trois qualités qu’on néglige au bureau.","Depuis que je travaille ainsi, mes comptes rendus sont deux fois plus courts et deux fois mieux lus.","Le télétravail rend meilleur, à condition de s’organiser."],"d":30},{"t":"Le télétravail, un entraînement · 1 min","x":["Le télétravail n’est pas un confort : c’est un entraînement.","Raison : à distance, personne ne devine ce que vous pensez. Vous devez écrire clairement, planifier votre journée, et rendre compte sans qu’on vous le demande.","[Pause.]","Ces trois qualités, on les laisse souvent de côté au bureau, parce qu’on peut les remplacer par une conversation au passage.","Depuis six mois, je travaille deux jours par semaine à la maison. Mes comptes rendus sont deux fois plus courts, et ils sont mieux lus.","Bien sûr, le télétravail isole, et il faut se forcer à garder le lien.","Mais utilisé avec méthode, il rend plus clair, plus autonome, plus fiable."],"d":60},{"t":"Le télétravail, un entraînement · 2 min","x":["Le télétravail n’est pas un confort : c’est un entraînement.","[Pause.]","Commençons par l’écrit. À distance, vous ne pouvez pas compter sur un geste, un regard, une conversation au café. Tout passe par des mots. Résultat : vous apprenez à écrire des messages qui se suffisent à eux-mêmes, avec le contexte, la demande et la date.","Ensuite, la planification. Personne ne passe derrière vous pour voir si vous avancez. Vous devez choisir vos priorités le matin, et savoir le soir ce que vous avez fait. Cette habitude, on la garde toute sa vie.","Enfin, le compte rendu. Quand on ne se voit pas, on doit rendre visible ce qu’on fait. Chaque vendredi, j’envoie cinq lignes : ce qui est fini, ce qui bloque, ce que je fais la semaine suivante.","[Pause.]","Depuis six mois, mes comptes rendus sont deux fois plus courts, et ma responsable me dit qu’elle ne pose plus de questions de relance.","Je sais ce qu’on répond : l’isolement, la perte du lien d’équipe. C’est vrai, et il faut le traiter : un point vidéo court tous les matins, un jour de présence par semaine, un vrai déjeuner de temps en temps.","Mais ce risque se gère, alors que les bénéfices, eux, restent.","Le télétravail, bien organisé, n’est pas moins de travail : c’est un travail plus net. Et c’est pour cela que je le défends."],"d":120},{"t":"Il faut échouer pour apprendre","x":["On apprend plus vite en échouant qu’en réussissant du premier coup.","Un échec montre exactement où l’on s’est trompé, alors qu’une réussite cache ses points faibles.","À mon premier exposé, j’ai lu mes notes sans lever la tête et la salle a décroché ; au second, j’ai regardé trois personnes et la salle m’a suivi.","Donc il faut accepter d’échouer tôt, pour réussir tard."]},{"t":"Le téléphone devrait être interdit en réunion","x":["Le téléphone devrait rester dans la poche pendant une réunion.","Il fragmente l’attention de celui qui le consulte, mais aussi de ceux qui le voient faire.","Dans une réunion de douze personnes, j’ai compté quatre regards qui tombaient vers l’écran à chaque notification, et la question posée a dû être répétée deux fois.","Une heure sans téléphone, c’est une réunion plus courte."]},{"t":"Un bon leader sait écouter avant de parler","x":["Un bon leader écoute avant de parler.","Celui qui parle en premier ferme la discussion, celui qui écoute l’ouvre.","Mon ancienne cheffe posait toujours trois questions avant de donner son avis, et ses décisions étaient rarement contestées.","Écouter n’est pas une faiblesse du pouvoir, c’est son meilleur outil."]},{"t":"Les études ne suffisent plus","x":["Un diplôme ne suffit plus pour trouver sa place.","Les recruteurs demandent aujourd’hui des preuves concrètes de ce qu’on sait faire.","Deux candidats avec le même diplôme, l’un avait construit un petit site pour une association, l’autre rien : le premier a été rappelé le lendemain.","Le diplôme ouvre la porte, les réalisations décident de qui entre."]},{"t":"Travailler à distance rend meilleur","x":["Le travail à distance peut rendre meilleur, à condition de s’organiser.","Il oblige à écrire clairement, à planifier et à rendre compte, trois qualités qu’on néglige au bureau.","Après six mois à distance, mes comptes rendus sont deux fois plus courts et deux fois mieux lus.","Le télétravail n’est pas un confort, c’est un entraînement."]},{"t":"Il faut dire non plus souvent","x":["Dire non est une compétence professionnelle.","Chaque oui à une demande secondaire est un non à une priorité.","J’ai refusé trois réunions non essentielles en un mois, et j’ai livré mon projet principal une semaine plus tôt.","Un non clair vaut mieux qu’un oui épuisé."]},{"t":"On devrait apprendre à s’ennuyer","x":["L’ennui est une compétence qu’on devrait enseigner.","C’est dans le vide que naissent les idées, les envies et les projets.","Mes meilleures idées me sont venues dans un train, sans écran, sans musique.","Apprendre à s’ennuyer, c’est apprendre à se rencontrer."]},{"t":"Le luxe est un art avant d’être un commerce","x":["Le luxe est d’abord un art du détail.","Ce qu’on achète, ce n’est pas seulement un objet, c’est des heures de savoir-faire.","Une maroquinerie artisanale peut passer quarante heures sur un seul sac, jusqu’au fil de la couture.","Le prix ne fait pas le luxe, c’est le soin."]},{"t":"Madagascar a un atout sous-estimé","x":["Madagascar a un atout sous-estimé : sa jeunesse.","Une population jeune, c’est une énergie, un marché et des talents à former.","À Antananarivo, de jeunes développeurs construisent déjà des applications pour des commerçants locaux avec peu de moyens.","Si l’on investit dans cette jeunesse, l’atout devient une force."]},{"t":"Un bon exemple vaut mieux qu’un long discours","x":["Un bon exemple convainc plus qu’un long discours.","On retient une histoire, on oublie une liste.","Pour expliquer l’épargne, j’ai raconté le prix d’un café par jour sur un an, et trois personnes ont ouvert un compte le soir même.","Avant de démontrer, montrez."]}],"connecteurs":[{"t":"Parler du prix","x":["Je voudrais dire une chose sur le prix.","Attention, je ne dis pas qu’il est bas.","Certes, il est plus élevé que la moyenne, mais il comprend trois mois de suivi.","Prenons le cas d’une cliente qui a posé dix questions la première semaine : elle a eu dix réponses.","Autrement dit, vous payez aussi les réponses."]},{"t":"Défendre un changement d’horaire","x":["Je voudrais dire une chose sur les horaires.","Attention, je ne dis pas que l’ancien rythme était mauvais.","Certes, il avait ses habitudes, mais il nous faisait perdre la fin de matinée.","Prenons le cas de la dernière réunion : elle a commencé à dix heures et demie, faute de quorum.","Autrement dit, décaler d’une heure, c’est gagner une matinée."]},{"t":"Défendre le voisinage","x":["Je voudrais dire une chose sur les voisins.","Attention, je ne dis pas qu’il faut tout partager avec eux.","Certes, on peut vivre sans les connaître, mais on vit mieux en les saluant.","Prenons le cas d’un immeuble de douze étages : un bonjour dans l’escalier suffit à rendre les clés oubliées moins dramatiques.","Autrement dit, un voisin est une assurance qui ne coûte qu’un sourire."]},{"t":"Soutenir un projet","x":["Je voudrais dire une chose sur ce projet.","Attention, je ne dis pas qu’il est sans risque.","Certes, il demande un effort, mais il règle un problème que nous avons depuis deux ans.","Prenons le cas de l’an dernier : nous avons perdu douze jours de travail à cause du même incident.","Autrement dit, ce projet n’est pas un coût, c’est une assurance."]},{"t":"Parler de la peur de se tromper","x":["Je voudrais dire une chose sur les erreurs.","Attention, je ne dis pas qu’il faut en faire exprès.","Certes, personne n’aime se tromper, mais personne n’apprend sans.","Prenons le cas d’un enfant qui apprend à marcher : il tombe, se relève, tombe moins.","Autrement dit, l’erreur n’est pas l’opposé de l’apprentissage, c’en est le chemin."]},{"t":"Défendre un délai","x":["Je voudrais dire une chose sur le délai.","Attention, je ne dis pas que nous sommes en retard.","Certes, le calendrier est serré, mais il est tenable si nous coupons deux options.","Prenons le cas du lot A : il est prêt et validé, il peut partir lundi.","Autrement dit, livrons l’essentiel à l’heure, le reste suivra."]},{"t":"Soutenir une collègue","x":["Je voudrais dire une chose sur Camille.","Attention, je ne dis pas qu’elle n’a jamais de retard.","Certes, elle arrive parfois en dernière minute, mais elle livre toujours.","Prenons le cas du dossier Lambert : tout le monde doutait, elle l’a bouclé en deux jours.","Autrement dit, jugez-la sur ce qu’elle rend, pas sur l’heure à laquelle elle le rend."]},{"t":"Défendre la marche","x":["Je voudrais dire une chose sur la marche.","Attention, je ne dis pas qu’elle remplace le sport.","Certes, courir brûle plus, mais marcher laisse penser.","Prenons le cas d’un problème qu’on tourne en rond : vingt minutes de marche, et la réponse arrive.","Autrement dit, la marche est un bureau à ciel ouvert."]},{"t":"Parler du télétravail","x":["Je voudrais dire une chose sur le télétravail.","Attention, je ne dis pas qu’il convient à tout le monde.","Certes, il isole parfois, mais il redonne du temps de transport.","Prenons le cas d’un salarié qui perd deux heures par jour dans les trains : sur un an, cela fait presque deux mois.","Autrement dit, la vraie question n’est pas où l’on travaille, mais combien de temps on récupère."]},{"t":"Parler de l’argent","x":["Je voudrais dire une chose sur l’argent.","Attention, je ne dis pas qu’il fait le bonheur.","Certes, il ne remplace ni l’amitié ni la santé, mais il achète du temps.","Prenons le cas d’une famille qui doit réparer son toit : sans épargne, elle s’endette.","Autrement dit, épargner, c’est acheter de la tranquillité à l’avance."]}],"recit":[{"t":"Premier jour de stage, trente minutes de retard","x":["Lundi matin, premier jour de stage, j’arrive avec trente minutes de retard.","La porte est fermée, toute l’équipe est déjà en réunion, et je n’ai ni badge ni numéro.","Je frappe, j’entre, je dis « Je suis en retard, je m’excuse, je suis Stephen », et je demande une chaise.","Une excuse courte suivie d’une action vaut mieux qu’une explication longue."]},{"t":"La panne de micro","x":["J’allais présenter devant soixante personnes, le micro est tombé en panne à cinq minutes de mon tour.","La salle était grande, et ma voix ne portait pas encore.","J’ai avancé d’un pas, j’ai respiré, et j’ai dit « Si vous m’entendez, levez la main ». Toutes les mains se sont levées.","Quand l’outil lâche, la voix reste, et demander à la salle la rend complice."]},{"t":"Le train raté","x":["Un jeudi matin, je rate le train pour un entretien important.","Le suivant arrive vingt minutes après l’heure du rendez-vous, et je n’ai pas de numéro à appeler.","J’ai écrit un message court à l’adresse du recruteur : « Je serai en retard de vingt minutes, je comprends si vous préférez reporter. »","Prévenir tôt, brièvement, c’est déjà montrer qu’on est fiable."]},{"t":"Mon premier client","x":["Un restaurateur m’a demandé un devis pour un site.","Je n’avais aucun prix de référence, et j’ai eu peur de demander trop.","J’ai calculé mes heures, ajouté une marge, et dit mon prix sans trembler, puis je me suis tu.","Le prix se dit une fois, simplement, et le silence fait le reste."]},{"t":"L’exposé oublié","x":["Un matin, je découvre que l’exposé est pour aujourd’hui, pas pour la semaine prochaine.","Aucune diapositive, aucune note, dix minutes devant moi.","J’ai écrit trois mots au tableau, j’ai raconté une histoire qui les reliait, et j’ai terminé par une question à la classe.","Une idée claire et trois mots valent mieux qu’un plan oublié."]},{"t":"Le client mécontent","x":["Un client m’appelle, furieux, parce qu’une livraison est en retard.","Il parle fort et ne me laisse pas répondre.","J’ai attendu qu’il termine, j’ai reformulé son problème en une phrase, puis proposé une solution et une date.","On désamorce une colère en montrant qu’on l’a comprise."]},{"t":"Mon premier jour de travail","x":["À dix-sept ans, premier jour de job d’été dans un restaurant.","Je ne connaissais personne, j’ai cassé deux verres avant midi.","Le chef m’a dit « tout le monde casse », m’a tendu un balai, et nous avons ri.","Un bon début n’est pas un début sans faute, c’est un début avec quelqu’un."]},{"t":"Le dossier perdu","x":["L’ordinateur plante, trois heures avant un rendu, et le dossier n’est pas sauvegardé.","Le temps manque et la panique monte.","J’ai éteint l’écran, repris une feuille, noté les trois idées principales, puis reconstruit le dossier plus court.","Le dossier perdu m’a appris à sauvegarder, et à aller à l’essentiel."]},{"t":"La question piège","x":["Lors d’une soutenance, un membre du jury me pose une question hors sujet.","Je n’avais pas la réponse.","J’ai dit « Je n’ai pas cette information, je vous la transmets demain », puis j’ai noté la question.","Avouer simplement ce qu’on ignore vaut mieux que bluffer."]},{"t":"Le dimanche du filet","x":["Enfant, je tenais un bout du filet de pêche de mon grand-père chaque dimanche matin.","Je m’ennuyais, et il ne parlait presque jamais.","Un jour, j’ai arrêté de regarder mes pieds et j’ai regardé ses mains.","On apprend souvent en silence, à côté de quelqu’un qui travaille."]}],"discours":[{"t":"Pourquoi cuisiner soi-même","x":["Imaginez qu’on vous tende un oignon et qu’on vous dise : faites-en un dîner.","Je vais vous dire trois choses : ce que cela change, ce que cela coûte, et comment s’y mettre.","D’abord, cela change le goût. On sait ce qu’il y a dans l’assiette, donc on y croit.","Ensuite, cela coûte moins. Un plat maison revient souvent à moitié prix du plat acheté.","Enfin, cela rapproche. On cuisine pour quelqu’un, et ce quelqu’un le sent.","Demain soir, un plat simple, deux chaises. Commencez par des pâtes, et invitez quelqu’un."]},{"t":"Prendre une petite décision","x":["On ne change pas de vie en un jour, mais on peut changer de matin.","Une décision, un rituel, un témoin.","Choisissez une chose minuscule, par exemple vous lever dix minutes plus tôt.","Faites-la toujours au même endroit, au même moment, pour que le corps l’apprenne.","Dites-la à quelqu’un, pour qu’elle devienne une promesse.","Choisissez, ce soir, votre dix minutes, et dites-le à une personne."]},{"t":"Savoir remercier","x":["Un merci bien dit pèse plus lourd qu’un cadeau mal choisi.","Regarder, préciser, laisser un silence.","Un merci adressé à l’écran n’arrive à personne.","« merci pour ton aide » est faible, « merci d’avoir relu mon dossier mardi soir » est fort.","Le merci a besoin d’une seconde pour arriver.","Aujourd’hui, remerciez quelqu’un avec un détail précis."]},{"t":"L’art de bien commencer","x":["La première phrase d’un discours décide de la deuxième.","Une image, une question, un chiffre.","Racontez un détail de la salle, et le public se sent présent.","Posez-la, puis taisez-vous deux secondes.","Un seul, et surprenant, expliqué tout de suite.","Pour votre prochaine prise de parole, écrivez trois ouvertures et gardez la plus courte."]},{"t":"Se préparer sans se figer","x":["Préparer, ce n’est pas apprendre par cœur, c’est savoir où l’on va.","L’idée, les mots-clés, la sortie.","Une phrase qui résume ce que vous voulez que le public retienne.","Les mots-clés : cinq mots sur une carte, pas plus.","La dernière phrase, écrite mot pour mot.","Cette semaine, préparez un exposé avec cinq mots-clés et une dernière phrase."]},{"t":"Oser demander de l’aide","x":["Demander de l’aide n’est pas avouer qu’on ne sait pas, c’est choisir d’aller plus loin.","Demander tôt, demander précis, remercier.","Une question posée au début coûte dix minutes, posée à la fin elle en coûte dix heures.","« peux-tu me montrer comment faire ça ? » vaut mieux que « je n’y arrive pas ».","On aide plus volontiers quelqu’un qui dit merci.","Aujourd’hui, posez la question que vous retardez depuis une semaine."]},{"t":"Gérer un échec","x":["Tout le monde a raté quelque chose, peu de gens savent en parler.","Nommer, comprendre, repartir.","Dire simplement ce qui n’a pas marché, sans adjectif.","Chercher une cause, pas un coupable.","Choisir un petit pas, et le faire dans la journée.","Pensez à un échec récent, et écrivez la première étape en une phrase."]},{"t":"Réussir un entretien","x":["Un entretien, c’est une conversation avec un enjeu.","Préparer trois histoires, poser deux questions, remercier à la fin.","Trois histoires vraies, qui montrent ce que vous savez faire.","Deux questions sur le poste, pour montrer que vous réfléchissez déjà à l’après.","Un merci précis, envoyé le soir même.","Écrivez dès ce soir vos trois histoires, une ligne chacune."]},{"t":"Pourquoi s’entraîner","x":["Personne n’est né orateur, tous les orateurs se sont entraînés.","La répétition, le retour, le plaisir.","Dire une phrase vingt fois la rend naturelle.","S’enregistrer montre ce qu’on ne sent pas.","On aime ce qu’on réussit.","Ce soir, enregistrez-vous trente secondes et écoutez."]},{"t":"Bien finir","x":["On se souvient de la dernière phrase plus que de la première.","Une promesse, une image, une demande.","Dire ce qu’on fera.","Boucler sur l’ouverture.","Dire ce qu’on attend du public.","Écrivez la fin de votre prochain discours en premier, et construisez le reste ensuite."]}],"debat":[{"t":"POUR : le télétravail comme droit","x":["Le télétravail devrait être un droit.","Il rend des heures de transport à ceux qui en perdent deux par jour.","Il ouvre l’emploi à ceux qui vivent loin des grandes villes.","On dit qu’on perd le lien d’équipe ; le lien se construit par des jours de présence choisis, pas subis.","Un droit encadré, pas une obligation."]},{"t":"CONTRE : la semaine de quatre jours","x":["La semaine de quatre jours n’est pas la bonne réponse partout.","Dans les métiers de service, quatre jours plus longs fatiguent plus qu’ils ne reposent.","Tous les secteurs ne peuvent pas fermer un jour de plus sans perdre des clients.","On cite des essais réussis ; ils concernent surtout des bureaux, pas des hôpitaux ni des commerces.","Oui à l’expérience, non à la règle unique."]},{"t":"POUR : l’IA dans la création artistique","x":["L’intelligence artificielle devrait être autorisée dans la création.","Elle est un outil, comme l’appareil photo l’a été pour la peinture.","Elle permet à ceux qui n’ont pas le matériel de créer.","On craint le vol d’œuvres ; la solution est la transparence et la rémunération, pas l’interdiction.","Un outil permis, des règles claires."]},{"t":"CONTRE : les réseaux avant quinze ans","x":["Les réseaux sociaux ne devraient pas être ouverts avant quinze ans.","Les algorithmes exploitent l’attention d’un cerveau qui se forme.","Le harcèlement en ligne suit l’enfant jusque dans sa chambre.","On dit que les jeunes s’en passeront difficilement ; ils se passent déjà de bien des choses utiles.","Un âge minimum, comme pour le permis."]},{"t":"POUR : le vote obligatoire","x":["Voter devrait être obligatoire.","Un scrutin élu par quarante pour cent des électeurs est un scrutin faible.","L’obligation pousse les partis à parler à tous, pas seulement aux convaincus.","On invoque la liberté ; on est déjà obligé de payer l’impôt et d’aller à l’école.","Un devoir léger pour une démocratie plus solide."]},{"t":"CONTRE : l’uniforme à l’école","x":["L’uniforme obligatoire n’est pas la solution.","Il règle l’apparence sans régler les inégalités.","Il coûte aux familles, et ces coûts sont rarement pris en charge.","On dit qu’il supprime les comparaisons ; elles se déplacent vers les chaussures ou le téléphone.","Mieux vaut éduquer au respect que cacher les différences."]},{"t":"POUR : publier les prix de fabrication du luxe","x":["Les marques de luxe devraient publier leurs coûts de fabrication.","La transparence justifie le prix par le savoir-faire.","Elle protège le client contre l’illusion de rareté.","On dit que le luxe vit du secret ; une marque solide n’a rien à craindre du détail.","La confiance coûte moins cher que le mystère."]},{"t":"CONTRE : l’interdiction du téléphone au collège","x":["Interdire le téléphone au collège ne suffit pas.","Il faut aussi apprendre à s’en servir, pas seulement à s’en passer.","L’interdiction se contourne, l’éducation reste.","On invoque la concentration ; elle s’obtient aussi avec des règles d’usage claires.","Poser un cadre et former, plutôt qu’interdire seulement."]},{"t":"POUR : une année de service civique","x":["Une année de service civique devrait être proposée à tous les jeunes.","Elle brasse des profils qui ne se croisent jamais.","Elle donne une première expérience concrète.","On craint le coût ; un jeune formé et engagé coûte moins cher que dix ans d’indifférence.","Une année pour mieux se connaître, et connaître les autres."]},{"t":"CONTRE : la note unique à l’école","x":["La note unique ne dit pas ce qu’un élève sait faire.","Une moyenne mélange des compétences très différentes.","Elle décourage ceux qui progressent sans atteindre le seuil.","On dit qu’elle est simple ; la simplicité n’est pas la justesse.","Un bilan par compétences, plus lisible et plus juste."]}],"objection":[{"t":"« C’est trop cher » · 30 s","x":["Je comprends que ce soit un investissement.","Mais la vraie question, c’est ce que ça vous coûte de ne pas le faire.","Avec ce suivi, deux élèves sur trois doublent leur temps de parole en trois mois.","Dites-moi quel résultat justifierait ce prix pour vous."],"d":30},{"t":"« C’est trop cher » · 1 min","x":["Je comprends : c’est un investissement, et vous voulez être sûr.","Mais regardons la question autrement. Combien vous coûte aujourd’hui le problème que ce programme résout ?","[Pause. Laissez répondre.]","Si vous perdez trois rendez-vous par semaine, à deux cents euros chacun, cela fait six cents euros par semaine.","Mon programme coûte quatre cents euros, une seule fois.","Sur trois mois, deux élèves sur trois ont doublé leur temps de parole sans notes.","Je ne vous promets pas un miracle : je vous propose un calcul. Quel résultat justifierait ce prix pour vous ?"],"d":60},{"t":"« C’est trop cher » · 2 min","x":["Je vous remercie de me le dire franchement : c’est précieux, parce que beaucoup de gens pensent cela sans l’exprimer.","[Pause.]","Je commence par être d’accord : oui, c’est un investissement, et on ne dépense pas quatre cents euros sans réfléchir.","Je vous propose de regarder trois choses ensemble.","Première chose : ce que vous payez. Quatre séances, un enregistrement à réécouter, un suivi par message pendant un mois. Ce n’est pas un cours : c’est un accompagnement.","Deuxième chose : ce que vous perdez aujourd’hui. Posez-vous la question : combien de rendez-vous, de ventes, d’occasions perdez-vous chaque semaine parce que le message ne passe pas ? Si c’est trois par semaine, à deux cents euros, c’est six cents euros par semaine.","[Pause.]","Troisième chose : ce que les autres ont obtenu. Sur les trois derniers mois, deux élèves sur trois ont doublé leur temps de parole sans notes. Je ne dis pas que ce sera pareil pour vous. Je dis que c’est mesurable.","Voici donc ma question : si ce programme vous faisait récupérer seulement la moitié des rendez-vous perdus, le prix vous paraîtrait-il encore trop élevé ?","[Silence. Laissez répondre.]","Et si le prix reste un obstacle, nous pouvons étaler le paiement en trois fois. Mais je préfère que nous parlions d’abord de ce que vous voulez obtenir."],"d":120},{"t":"« Je dois réfléchir » · 30 s","x":["Bien sûr, c’est normal de prendre le temps.","Sur quoi voulez-vous réfléchir : le prix, le moment, ou le contenu ?","Si je sais ce qui vous retient, je peux vous répondre dès aujourd’hui.","Dites-moi ce qui manque, et je vous l’apporte avant demain."],"d":30},{"t":"« Je dois réfléchir » · 1 min","x":["Bien sûr, c’est normal de prendre le temps, et je ne veux pas que vous décidiez sous pression.","Mais je me pose une question : sur quoi voulez-vous réfléchir précisément ? Le prix, le moment, le contenu, ou autre chose ?","[Pause.]","En général, quand un point est clair, la décision se prend dans la journée. Quand rien n’est dit, la réflexion se prolonge, et on n’y revient plus.","Alors dites-moi : qu’est-ce qui vous retient ?","[Écoutez.]","Je note ce point, et je vous apporte une réponse avant demain midi."],"d":60},{"t":"« Je dois réfléchir » · 2 min","x":["Bien sûr, prenez le temps de réfléchir. Je préfère un client qui décide en conscience à un client qui dit oui pour me faire plaisir.","[Pause.]","Je vous propose simplement de rendre cette réflexion utile. Quand quelqu’un me dit « je dois réfléchir », il y a presque toujours une raison précise derrière : le prix, la période, une hésitation sur le contenu, ou l’envie de comparer avec une autre offre.","Je ne vous demande pas de me la dire si vous n’en avez pas envie. Mais si vous me la dites, je peux faire trois choses : répondre tout de suite, vous donner un chiffre ou une preuve qui manque, ou vous dire honnêtement que mon offre n’est pas faite pour vous.","[Pause.]","Je prends un exemple. La semaine dernière, une cliente m’a dit la même chose. En posant la question, nous avons découvert que le prix n’était pas le problème : c’était le calendrier. Nous avons déplacé le démarrage de deux semaines, et elle a signé le lendemain.","Alors, de votre côté, qu’est-ce qui pèse le plus : le prix, la date, ou le contenu ?","[Silence. Écoutez.]","Merci. Je note ce point, je vous envoie une réponse précise avant demain midi, et vous déciderez ensuite en toute liberté."],"d":120},{"t":"« Mon concurrent est moins cher » · 30 s","x":["C’est vrai, d’autres offres sont moins chères, et il est normal de comparer.","Je ne parlerai pas de mon concurrent : je vais vous dire ce que mon prix comprend.","Un suivi de trois mois, un point chaque semaine, un résultat mesuré.","Si son offre l’inclut aussi, prenez-la. Sinon, la différence, c’est le risque que vous payez."],"d":30},{"t":"« Mon concurrent est moins cher » · 1 min","x":["C’est vrai, d’autres offres sont moins chères, et je trouve normal que vous compariez.","Je ne vais pas parler de mon concurrent : je ne le connais pas assez, et ce ne serait pas juste.","Je vais plutôt vous dire ce que mon prix comprend : un suivi de trois mois, un point chaque semaine, et un résultat mesuré.","[Pause.]","Pour comparer, posez-lui trois questions. Le suivi est-il inclus ? Le délai est-il garanti ? Que se passe-t-il si ça ne marche pas ?","Si les trois réponses sont oui, c’est une bonne offre, et je vous dirai de la prendre.","Si elles sont non, alors la différence de prix, c’est ce que vous payez en risque."],"d":60},{"t":"« Mon concurrent est moins cher » · 2 min","x":["C’est vrai, vous trouverez moins cher, et je ne vais pas vous dire le contraire. Comparer est une bonne idée.","[Pause.]","Je ne vais pas non plus critiquer mon concurrent : je ne le connais pas assez, et ce serait de mauvaise foi.","Je vous propose plutôt une méthode de comparaison, valable pour moi comme pour n’importe qui.","Première question : qu’est-ce qui est inclus ? Un prix bas qui laisse de côté le suivi, les corrections ou la formation n’est pas comparable à un prix qui les contient.","Deuxième question : que se passe-t-il quand quelque chose ne va pas ? Y a-t-il quelqu’un à qui parler, avec quel délai de réponse ?","Troisième question : quelles preuves peut-on voir ? Des chiffres, des témoignages, des exemples vérifiables.","[Pause.]","Chez moi, voici les réponses. Le suivi est inclus pendant trois mois. Je réponds dans la journée. Et je peux vous donner trois noms de clients que vous pouvez appeler.","Si l’autre offre répond aussi bien à ces trois questions, alors elle est meilleure que la mienne sur le prix, et vous avez raison de la prendre.","Si elle ne répond pas, alors la différence de prix n’est pas une économie : c’est un risque que vous achetez.","Je vous laisse vérifier, et je reste joignable pour toute question."],"d":120},{"t":"« C’est trop cher »","x":["« C’est trop cher. »","C’est un investissement, et je comprends que vous vouliez être sûr.","La vraie question, c’est ce que ça vous coûte de ne pas le faire.","Sur trois mois, deux élèves sur trois ont doublé leur temps de parole sans notes.","Dites-moi quel résultat justifierait ce prix pour vous."]},{"t":"« Je dois réfléchir »","x":["« Je dois réfléchir. »","Bien sûr, c’est une bonne décision à prendre sans précipitation.","Sur quoi voulez-vous réfléchir, précisément : le prix, le moment, ou le contenu ?","En général, quand un point est clair, la décision se prend dans la journée.","Dites-moi ce qui manque, et je vous l’apporte avant demain."]},{"t":"« Je peux le faire seul »","x":["« Je peux le faire seul. »","C’est vrai, beaucoup de choses se font seul.","La question est de savoir en combien de temps et avec quelle assurance.","Ceux que j’accompagne gagnent en moyenne trois mois sur leur projet.","Voulez-vous gagner ces trois mois ?"]},{"t":"« Mon cousin le fait gratuitement »","x":["« Mon cousin le fait gratuitement. »","C’est une belle solution, et la famille est précieuse.","Gratuit ne veut pas dire sans coût : délais, disponibilité, garantie.","Sur mes derniers projets, les délais ont été tenus à cent pour cent, avec un contrat.","Qu’est-ce qui compte le plus pour vous : le prix ou la certitude ?"]},{"t":"« Ce n’est pas le bon moment »","x":["« Ce n’est pas le bon moment. »","Le moment compte, je suis d’accord.","Qu’est-ce qui rendrait le moment bon ?","La plupart de mes clients disent attendre un moment idéal qui n’arrive jamais.","Si on commençait petit, cette semaine, avec une première étape ?"]},{"t":"« Je ne vous connais pas »","x":["« Je ne vous connais pas. »","C’est normal, nous nous rencontrons à peine.","C’est pour cela que je propose un premier échange gratuit, sans engagement.","Voici trois témoignages de personnes qui ont commencé ainsi.","Voulez-vous commencer par ce premier pas ?"]},{"t":"« Les résultats sont-ils garantis ? »","x":["« Les résultats sont-ils garantis ? »","Non, personne honnête ne peut garantir un résultat.","Ce que je garantis, c’est le travail, le suivi et la transparence.","Voici les chiffres de mes derniers élèves, avec leurs points de départ.","Êtes-vous prêt à faire votre part ?"]},{"t":"« C’est trop long »","x":["« C’est trop long. »","Le temps est une vraie ressource.","Ce n’est pas la durée qui compte, mais l’effort par jour.","Dix minutes par jour suffisent, comme le montrent mes élèves les plus réguliers.","Quel créneau de dix minutes pouvez-vous tenir ?"]},{"t":"« Je n’ai pas le budget »","x":["« Je n’ai pas le budget. »","Je comprends, le budget est une contrainte réelle.","Regardons ce que vous pouvez engager, et ce que ça rapporte.","Un module à bas prix existe, et je propose aussi un paiement en trois fois.","Quelle option vous semble tenable ?"]},{"t":"« Je vais comparer »","x":["« Je vais comparer avec d’autres. »","Comparer est une bonne idée.","Voici les trois critères à regarder : le suivi, les preuves, la clarté du prix.","Je vous donne mes chiffres, comparez les leurs.","Revenez vers moi demain, avec vos questions."]}],"reprise":[{"t":"Coupé en réunion","x":["Je me permets de terminer, il me reste deux points.","Premièrement, le coût : il baisse de quinze pour cent.","Deuxièmement, le délai : nous gagnons trois semaines.","Voilà pourquoi je propose de commencer par le délai. Je vous écoute."]},{"t":"Interrompu par un collègue","x":["Merci, ta remarque est utile, je la note.","Laisse-moi finir ma phrase, et je reviens tout de suite sur ce point.","Je disais donc : la livraison est prévue vendredi.","Maintenant, dis-moi ce qui te gêne."]},{"t":"Coupé par un client","x":["Vous avez raison de poser la question.","Permettez-moi de finir en une phrase, puis je vous réponds complètement.","Le prix comprend le suivi pendant six mois.","Votre question, maintenant : je vous écoute."]},{"t":"Coupé par la voix de l’enregistrement","x":["[Le message de l’enregistrement couvre ta voix. Tu t’arrêtes.]","Je vous laisse un instant, le temps que ce message se termine.","[Silence, regard calme.]","Je reprends : l’idée tient en une phrase, et la voici."]},{"t":"Face à quelqu’un qui parle plus fort","x":["[Tu baisses la voix, tu ralentis.]","Je vais parler plus doucement, parce que ce que j’ai à dire compte.","Une seule chose : nous n’avons pas les mêmes chiffres.","Regardons-les ensemble, un par un."]},{"t":"Pendant un entretien","x":["Si vous me permettez, je termine mon exemple, il est important.","Lors de mon dernier stage, j’ai géré un budget de dix mille euros.","Résultat : nous avons livré avec une semaine d’avance.","Voilà ce que je peux apporter ici. Votre question était sur ma méthode ?"]},{"t":"Pendant une soutenance","x":["Je réponds à votre question dans un instant, il me reste un résultat à présenter.","Deux résultats : une baisse des coûts de vingt pour cent, une hausse de satisfaction.","Voilà. Votre question portait sur la méthode, je vous réponds.","Nous avons interrogé cent personnes, sur trois mois."]},{"t":"Au téléphone","x":["Je vous entends, et je vous réponds juste après.","Laissez-moi vous dire en dix secondes l’essentiel.","L’offre est valable jusqu’à vendredi, au même prix.","Je vous écoute, dites-moi ce qui vous inquiète."]},{"t":"En visio","x":["[Plusieurs voix se superposent.] Je vous propose qu’on se passe la parole.","Je finis ma phrase, puis je laisse la parole à Claire.","Ce que je voulais dire : nous sommes dans les temps.","Claire, à toi."]},{"t":"Face à un proche","x":["Je t’écoute depuis tout à l’heure, laisse-moi finir une seconde.","Je ne te reproche rien, je voudrais juste qu’on m’entende aussi.","Ce que je ressens, c’est de la fatigue, pas de la colère.","Maintenant, dis-moi ce que tu voulais dire."]}],"interview":[{"t":"Interview : l’association","x":["« Combien de membres ? » — « Quarante-deux membres actifs, dont dix-sept depuis plus d’un an. »","« N’est-ce pas peu ? » — « C’est modeste, et c’est le chiffre que je peux garantir ; nous visons soixante avant juin. »","« Pourquoi vous ? » — « Parce que j’ai connu le manque de lieu pour s’entraîner à parler. »"]},{"t":"Interview : l’application","x":["« Combien d’utilisateurs ? » — « Cent vingt, dont quarante actifs chaque semaine. »","« Elle est gratuite, comment gagnez-vous de l’argent ? » — « Aujourd’hui nous ne gagnons pas encore ; l’objectif est d’abord la qualité. »","« Pourquoi vous ? » — « Parce que j’utilise moi-même cet outil tous les jours. »"]},{"t":"Interview : un stage","x":["« Combien de dossiers traitiez-vous ? » — « Environ dix par semaine. »","« Qu’avez-vous raté ? » — « Une facture envoyée en double ; je l’ai corrigée le jour même et mis en place un contrôle. »","« Pourquoi ce métier ? » — « Parce que j’aime que les choses soient bien rangées pour que d’autres avancent. »"]},{"t":"Interview : un commerce","x":["« Quel chiffre d’affaires ? » — « Je préfère ne pas donner le montant exact, mais il a progressé de vingt pour cent. »","« Vos concurrents sont moins chers. » — « Oui, et ils ne proposent pas le suivi que nous offrons. »","« Pourquoi vous ? » — « Parce que c’est le métier de ma famille, et que je veux le moderniser. »"]},{"t":"Interview : un projet étudiant","x":["« Quel budget ? » — « Deux mille euros, financés à moitié par l’école. »","« Est-ce réaliste ? » — « Oui si nous tenons trois jalons ; sinon, nous réduisons le périmètre. »","« Pourquoi ce projet ? » — « Parce que j’ai connu ce problème personnellement. »"]},{"t":"Interview : un changement de poste","x":["« Combien de temps dans l’entreprise ? » — « Deux ans et trois mois. »","« Vous partez donc fâché ? » — « Non, je pars avec reconnaissance et l’envie d’apprendre ailleurs. »","« Qu’est-ce qui vous motive ? » — « Voir un projet commencé et fini. »"]},{"t":"Interview : un échec","x":["« Combien avez-vous perdu ? » — « Environ trois mille euros. »","« C’est votre faute ? » — « En partie : j’ai mal estimé la demande. »","« Qu’avez-vous appris ? » — « À tester petit avant de lancer grand. »"]},{"t":"Interview : une réussite","x":["« Quel résultat ? » — « Trente pour cent de clients en plus en six mois. »","« N’est-ce pas de la chance ? » — « La chance existe, mais nous avons testé sept versions avant d’y arriver. »","« À qui le devez-vous ? » — « À l’équipe, et à un client qui nous a dit la vérité. »"]},{"t":"Interview : un livre","x":["« Combien d’exemplaires ? » — « Trois cents, vendus en direct. »","« Pourquoi ne pas passer par un éditeur ? » — « Je veux d’abord mesurer l’intérêt réel. »","« Pourquoi écrire ? » — « Parce que je pense mieux avec un stylo. »"]},{"t":"Interview : une prise de parole","x":["« Combien de personnes dans la salle ? » — « Environ soixante. »","« Avez-vous eu peur ? » — « Oui, et je l’ai dit dès la première phrase. »","« Que retenez-vous ? » — « Qu’on tient mieux quand on assume le trac. »"]}],"aveu":[{"t":"Chiffre inconnu : désabonnement","x":["« Quel est le taux de désabonnement ? »","Je n’ai pas le chiffre exact avec moi.","Autour d’un abonné sur dix par an, d’après mes derniers relevés.","Je vous envoie le chiffre vérifié avant vendredi."]},{"t":"Chiffre inconnu : budget","x":["« Quel est le budget total ? »","Je n’ai pas le montant définitif.","Entre dix et douze mille euros.","Je vous le confirme lundi, après la réunion de finance."]},{"t":"Détail inconnu : date","x":["« Quelle est la date de livraison ? »","Je ne peux pas vous donner une date certaine aujourd’hui.","Plutôt dans la deuxième quinzaine de mars.","Je vous donne une date ferme jeudi."]},{"t":"Détail inconnu : concurrents","x":["« Combien de concurrents sur le marché ? »","Je n’ai pas de liste complète.","J’en connais cinq principaux.","Je vous envoie la liste complète demain matin."]},{"t":"Chiffre inconnu : clients","x":["« Combien de clients avez-vous eus cette année ? »","Le total exact m’échappe.","Une trentaine.","Je vérifie dans mes fichiers et vous écris ce soir."]},{"t":"Détail inconnu : règlement","x":["« Cette règle s’applique-t-elle aux étudiants ? »","Je ne suis pas sûr.","Je crois que oui, mais sous conditions.","Je vérifie auprès du service concerné et je reviens vers vous demain."]},{"t":"Chiffre inconnu : audience","x":["« Combien de personnes vous suivent ? »","Je n’ai pas le chiffre à jour.","Environ deux mille.","Je regarde les statistiques ce soir et vous envoie la capture."]},{"t":"Détail inconnu : prix concurrent","x":["« Combien coûte le concurrent ? »","Je ne connais pas son tarif précis.","À peu près vingt pour cent moins cher, mais sans suivi.","Je compare les offres et je vous envoie le tableau."]},{"t":"Question hors sujet","x":["« Que pensez-vous de l’élection ? »","Ce n’est pas mon domaine et je n’ai pas d’avis informé.","Je préfère ne pas répondre à la place des spécialistes.","Revenons à notre sujet, je peux traiter votre question sur le projet."]},{"t":"Chiffre sourcé plus tard","x":["« D’où vient ce chiffre ? »","Je l’ai retenu d’une lecture, mais je ne retrouve pas la source sur-le-champ.","Il m’a semblé autour de soixante pour cent.","Je retrouve la source et je vous l’envoie avant ce soir, sinon je retire le chiffre."]}],"virelangue":[{"t":"Série 1 · les classiques","x":["Cinq chiens chassent six chats.","Ton thé t’a-t-il ôté ta toux ?","Pauline plie ses pulls puis peint.","Le roi rit, la reine râle."]},{"t":"Série 2 · les sifflantes","x":["Si six scies scient six cyprès, six cent six scies scient six cent six cyprès.","Sept sages sceptiques scandent six sentences sensées.","Ce sont six saucissons secs.","Ces cinq sages sont sûrs : seule la sagesse sauve."]},{"t":"Série 3 · les chuintantes","x":["Treize tristes trompettes trompent trois très traîtres tritons.","Un chef chic cherche chaque jour ses chaussures chez Jules.","Natacha n’attacha pas son chat Pacha qui s’échappa.","Gros gras grand grain d’orge."]},{"t":"Série 4 · les « p » et les « b »","x":["Papa prépare patiemment des pâtes pour Paul.","Bébé boit beaucoup de bon bouillon bien bouillant.","Panier, piano, panier, piano.","Pauline plie ses pulls puis peint."]},{"t":"Série 5 · les « r »","x":["Le roi rit, la reine râle.","Le roi rit, la reine rage, le rat rend le riz rare.","Le ver vert va vers le verre vert.","Tu as vu la rue où roule la roue ?"]},{"t":"Série 6 · les « t » et les « d »","x":["Dix dindons dodus dînent dans un dôme doré.","Trois tortues trottaient sur un trottoir très étroit.","Didon dîna, dit-on, du dos d’un dodu dindon.","Zoé s’amuse, Rose s’excuse, Rosa refuse."]},{"t":"Série 7 · les « g » et les « f »","x":["Gros gras grand grain d’orge.","Fruits frais, fruits cuits, fruits frits.","Quand Coco croque cinq carottes, Gaston garde ses gâteaux.","La belle boule bien bleue brille."]},{"t":"Série 8 · les voyelles qui roulent","x":["Lou lit, Louis lit, lui lit aussi.","Je veux et j’exige d’exquises excuses.","Tu as vu la rue où roule la roue ?","Ton thé t’a-t-il ôté ta toux ?"]},{"t":"Série 9 · les longues phrases","x":["Un chasseur sachant chasser doit savoir chasser sans son chien.","Les chaussettes de l’archiduchesse sont-elles sèches, archi-sèches ?","Si six scies scient six cyprès, six cent six scies scient six cent six cyprès.","Natacha n’attacha pas son chat Pacha qui s’échappa."]},{"t":"Série 10 · tout mélangé","x":["Les poules du couvent couvent.","Ce sont six saucissons secs.","Trois tortues trottaient sur un trottoir très étroit.","Panier, piano, panier, piano."]}],"proverbe":[{"t":"Petit à petit","x":["« Petit à petit, l’oiseau fait son nid. »","La régularité construit plus que l’élan.","Ma voisine a écrit une page par jour pendant un an, et elle a un livre.","Ne méprisez pas les petits gestes répétés."]},{"t":"Qui ne tente rien","x":["« Qui ne tente rien n’a rien. »","Sans essai, il n’y a pas de résultat.","J’ai envoyé dix candidatures, neuf silences, un oui.","Le oui se cache derrière les silences."]},{"t":"Pierre qui roule","x":["« Pierre qui roule n’amasse pas mousse. »","Changer sans cesse empêche de s’installer.","Un ami a changé six fois de projet en deux ans, sans finir aucun.","Parfois, il faut rester pour récolter."]},{"t":"L’habit ne fait pas le moine","x":["« L’habit ne fait pas le moine. »","L’apparence ne dit pas tout.","Un client en jean m’a signé le plus gros contrat de l’année.","Ne jugez pas avant d’avoir écouté."]},{"t":"Mieux vaut tard que jamais","x":["« Mieux vaut tard que jamais. »","Commencer en retard vaut mieux que ne pas commencer.","À vingt-deux ans, j’ai pris ma première leçon de guitare.","Le bon moment, c’est maintenant."]},{"t":"Chat échaudé","x":["« Chat échaudé craint l’eau froide. »","Une mauvaise expérience rend méfiant, même à tort.","Après une prise de parole ratée, j’ai évité les scènes pendant un an.","Ne laissez pas un seul échec décider de tout."]},{"t":"On n’apprend pas aux vieux singes","x":["« Ce n’est pas à un vieux singe qu’on apprend à faire la grimace. »","L’expérience est difficile à corriger.","Mon oncle a refusé d’utiliser un téléphone récent pendant dix ans.","L’expérience est utile à condition de rester curieux."]},{"t":"Après la pluie","x":["« Après la pluie, le beau temps. »","Les épreuves finissent.","Après un mauvais trimestre, mon équipe a signé trois clients en un mois.","Tenez, le temps tourne."]},{"t":"Les petits ruisseaux","x":["« Les petits ruisseaux font les grandes rivières. »","De petites sommes ou de petits efforts s’additionnent.","Deux mille ariary par jour, au bout d’un an, font un téléphone.","Commencez petit, mais commencez."]},{"t":"Rien ne sert de courir","x":["« Rien ne sert de courir, il faut partir à point. »","Mieux vaut être prêt que pressé.","J’ai préparé trois semaines un exposé de dix minutes, et il est passé sans effort.","La préparation est la vitesse cachée."]}],"arrivee":[{"t":"Entrer dans une salle","x":["[Tu t’arrêtes à la porte, tu respires.]","Bonjour à tous, merci de m’accueillir.","[Deux secondes de silence, regard posé sur trois personnes.]","Je vais vous parler de quelque chose de simple, et de très important."]},{"t":"Entrer en réunion","x":["[Tu entres calmement, tu t’assois sans bruit.]","Bonjour, merci d’être là, je commence par l’essentiel.","Nous avons une décision à prendre aujourd’hui.","Voici les trois options."]},{"t":"Entrer à un entretien","x":["[Tu souris, tu serres la main, tu t’assois quand on t’invite.]","Bonjour, merci de me recevoir.","Je suis venu avec une idée claire de ce que je peux apporter.","Je vous écoute pour commencer, ou je me présente en une minute, comme vous préférez."]},{"t":"Entrer sur scène","x":["[Tu marches lentement jusqu’au centre.]","[Tu poses les yeux sur le fond de la salle. Silence.]","Bonsoir.","Ce soir, je voudrais vous raconter une histoire vraie."]},{"t":"Entrer dans un appel","x":["Bonjour, c’est Stephen, est-ce que j’appelle au bon moment ?","[Tu attends la réponse.]","Merci. Je serai bref : j’ai vu votre activité, et j’ai une idée pour vous.","Puis-je vous la présenter en trente secondes ?"]},{"t":"Entrer chez un client","x":["[Tu sonnes, tu souris, tu dis ton nom avant d’entrer.]","Bonjour, Stephen, nous avions rendez-vous à dix heures.","Merci de me recevoir chez vous.","Montrez-moi d’abord comment vous travaillez, je regarde et j’écoute."]},{"t":"Entrer devant des élèves","x":["[Tu poses tes affaires, tu regardes la classe.]","Bonjour, on commence.","[Tu attends le calme sans lever la voix.]","Aujourd’hui, un seul objectif : que chacun sorte avec une idée claire."]},{"t":"Entrer à un dîner","x":["[Tu entres avec un petit cadeau, tu souris.]","Bonsoir, merci de m’avoir invité.","Je ne connais personne, alors je vais commencer par la dame en bleu : on s’est déjà croisés ?","[Sourire.]"]},{"t":"Entrer en visio","x":["[Tu allumes ta caméra, tu respires.]","Bonjour à tous, vous m’entendez bien ?","Merci d’être là. Je vous propose trois points en vingt minutes.","Commençons par le premier."]},{"t":"Entrer après un retard","x":["[Tu entres, tu ne cours pas.]","Je vous prie de m’excuser pour ce retard, ce n’est pas un manque de respect.","Je vous remercie d’avoir commencé sans moi.","Je prends le fil ici, et je vous rattrape."]}],"bascule":[{"t":"De l’émotion au chiffre","x":["« Quand j’ai vu ma mère compter les œufs à la main chaque soir, j’ai compris. »","« Et ce soir-là, j’ai décidé de chiffrer. »","« Résultat : quarante minutes gagnées par jour. »"]},{"t":"De la peur au plan","x":["« J’ai eu peur, une vraie peur. »","« Mais la peur donne une liste. »","« Trois étapes, une par jour, à partir de demain. »"]},{"t":"De l’histoire à la leçon","x":["« Un jour, un client m’a rappelé trois fois pour la même chose. »","« Ce jour-là, j’ai compris. »","« On répète quand on n’est pas entendu. Alors écoutons. »"]},{"t":"Du problème à la promesse","x":["« Aujourd’hui, beaucoup de gens parlent sans être entendus. »","« Et si on changeait ça ? »","« Je vous promets quatre semaines pour parler avec clarté. »"]},{"t":"Du doute à l’action","x":["« Je me suis longtemps demandé si j’avais le droit de me lancer. »","« Puis un matin, j’ai envoyé le premier message. »","« Faites le vôtre aujourd’hui. »"]},{"t":"De la blague au sérieux","x":["« On m’a dit que j’avais deux défauts : je parle trop vite, et je parle trop. »","« Plus sérieusement, »","« La vitesse est un choix, et on peut le changer. »"]},{"t":"De la nostalgie à l’avenir","x":["« Je me souviens de la cour de mon école. »","« Mais je ne suis pas ici pour regarder en arrière. »","« Je suis ici pour ce qu’on va y construire. »"]},{"t":"Du fait personnel au collectif","x":["« J’ai raté mon premier oral. »","« Et je ne suis pas le seul. »","« Ensemble, on peut apprendre à ne plus rater. »"]},{"t":"Du constat à l’appel","x":["« Chaque année, des idées meurent faute d’être dites. »","« Et si la vôtre était la prochaine ? »","« Dites-la ce soir, à une personne. »"]},{"t":"De la critique à la reconnaissance","x":["« On m’a reproché d’être trop calme. »","« Et je les remercie. »","« Parce que ce calme m’a permis d’écouter. »"]}],"simple":[{"t":"Expliquer un mot","x":["Un mot, une phrase.","« Un budget, c’est une promesse faite à son argent. »","« Chaque mois, je décide où il va avant qu’il parte. »","« Simple, non ? »"]},{"t":"Expliquer un prix","x":["« Le prix, c’est ce que vous payez, la valeur, c’est ce que vous gardez. »","« Un manteau à cent euros, porté dix ans, coûte dix euros par an. »","« Regardez la durée, pas l’étiquette. »"]},{"t":"Expliquer une méthode","x":["« Ma méthode : dire, répéter, ajuster. »","« Je dis la phrase, je la répète dix fois, je l’ajuste. »","« Trois verbes, et c’est tout. »"]},{"t":"Expliquer un retard","x":["« J’ai pris du retard, voici pourquoi. »","« Le fournisseur a livré mardi au lieu de lundi. »","« Nouvelle date : vendredi. »"]},{"t":"Expliquer un métier","x":["« Mon métier : rendre simple ce qui est compliqué. »","« Je transforme dix pages en une page. »","« C’est tout le travail. »"]},{"t":"Expliquer un objectif","x":["« Mon objectif : soixante membres avant juin. »","« Chaque semaine, j’en invite cinq. »","« Trois mois, soixante. »"]},{"t":"Expliquer une règle","x":["« Notre règle : un seul sujet par réunion. »","« La dernière réunion a duré vingt minutes au lieu de soixante. »","« Simple, efficace. »"]},{"t":"Expliquer un choix","x":["« J’ai choisi l’option B. »","« Elle coûte moins cher et se livre plus vite. »","« C’est la plus raisonnable. »"]},{"t":"Expliquer un échec","x":["« Nous avons échoué sur un point. »","« Le message n’a pas été envoyé à temps. »","« La prochaine fois, on programme l’envoi. »"]},{"t":"Expliquer une idée neuve","x":["« Et si on enregistrait chaque réunion ? »","« Celui qui est absent peut l’écouter dans le train. »","« Moins de répétitions, plus de clarté. »"]}],"ouverture":[{"t":"Appel à un restaurateur","x":["« Bonjour, je suis Stephen, je crée des menus numériques pour restaurants. »","« Je vous appelle parce que j’ai vu votre carte sur Instagram, très soignée. »","« Aujourd’hui, comment vos clients découvrent-ils vos plats ? »"]},{"t":"Appel à une école","x":["« Bonjour, je m’appelle Stephen, j’anime des ateliers de prise de parole. »","« Je vous contacte parce que vos élèves présentent des exposés chaque trimestre. »","« Comment les préparez-vous aujourd’hui ? »"]},{"t":"Message à un recruteur","x":["« Bonjour, je suis Stephen, étudiant en marketing de luxe. »","« Votre offre de chef de projet correspond à deux de mes expériences. »","« Auriez-vous quinze minutes cette semaine ? »"]},{"t":"Appel à une boutique","x":["« Bonjour, ici Stephen, je développe des outils de gestion pour commerçants. »","« Je vous appelle car beaucoup de boutiques perdent du temps sur leurs stocks. »","« Comment suivez-vous vos stocks en ce moment ? »"]},{"t":"Rencontre en salon","x":["« Bonjour, j’aime votre stand. »","« Je cherche justement un partenaire pour mon projet. »","« Qu’est-ce qui vous amène ici ? »"]},{"t":"Appel à un ancien contact","x":["« Bonjour, c’est Stephen, on s’est rencontrés à la conférence de mars. »","« Je repense à notre discussion sur les formations. »","« Est-ce toujours un sujet pour vous ? »"]},{"t":"Appel à une association","x":["« Bonjour, je m’appelle Stephen, j’ai présidé une association de prise de parole. »","« Je vous appelle pour proposer un atelier gratuit. »","« Quelles sont vos dates libres ? »"]},{"t":"Message LinkedIn","x":["« Bonjour, j’ai lu votre article sur la marque employeur. »","« Il rejoint mon travail sur le luxe. »","« Puis-je vous poser une question rapide ? »"]},{"t":"Appel à un hôtel","x":["« Bonjour, je suis Stephen, étudiant en hospitality management. »","« Je prépare une étude sur l’accueil. »","« Auriez-vous dix minutes avec votre responsable ? »"]},{"t":"Appel de relance","x":["« Bonjour, c’est Stephen, nous avons échangé mardi. »","« Je reviens avec le chiffre promis. »","« Avez-vous un instant pour le voir ensemble ? »"]}],"ratio":[{"t":"Réunion de dix minutes","x":["Merci d’avoir pris ces dix minutes. Je commence par une question : qu’est-ce qui compte le plus pour vous cette année ?","[Écoute. Quatre minutes, sans interrompre.]","Si je résume : vous voulez gagner du temps sans perdre en qualité. C’est bien cela ?","Voici ce que je vous propose, en trois minutes, avec un exemple. Qu’en pensez-vous ?"]},{"t":"Appel découverte","x":["Bonjour, je ne vais pas vous vendre quelque chose ce matin, je veux d’abord vous comprendre.","Comment se passe votre journée type ? Qu’est-ce qui vous fait perdre le plus de temps ?","[Écoute, notes, relance :] Et quand cela arrive, vous faites quoi ?","D’accord. Je reviens vers vous avec une proposition courte, adaptée à ce que vous m’avez dit."]},{"t":"Entretien","x":["Avant de répondre, une précision : vous cherchez quelqu’un d’autonome, ou quelqu’un qui s’intègre vite ?","[Écoute la réponse.]","Dans ce cas, je vous donne un exemple. Lors de mon alternance, j’ai pris en charge une tâche inconnue.","Je l’ai finie en deux semaines, et j’ai formé un collègue. Est-ce le profil que vous cherchez ?"]},{"t":"Réunion d’équipe","x":["Avant de décider, je voudrais entendre chacun en deux minutes.","Camille, d’abord. Qu’est-ce qui te bloque ?","[Écoute.] Merci. Et toi, Karim ?","Je vois deux solutions. Laquelle vous semble la plus réaliste ?"]},{"t":"Vente en boutique","x":["Bonjour, prenez votre temps. Qu’est-ce que vous cherchez, pour quelle occasion ?","[Écoute. Elle parle d’un mariage en juin.]","Si je comprends bien, vous voulez quelque chose d’élégant mais confortable. Je vous montre deux pièces.","Essayez celle-ci. Dites-moi ce que vous ressentez."]},{"t":"Rendez-vous client","x":["Merci de nous recevoir. Pour bien démarrer, parlez-moi de votre activité, comme à un ami.","[Écoute pendant quatre minutes.]","Vous avez dit trois choses : la lenteur, les erreurs, le coût. Laquelle est la plus urgente ?","Alors commençons par celle-là. Voici comment je vois les choses."]},{"t":"Débat","x":["Je veux d’abord comprendre votre position : qu’est-ce qui vous inquiète dans cette idée ?","[Écoute.]","Si je reformule : vous craignez les coûts cachés. C’est bien cela ?","Je les prends au sérieux. Voici un chiffre, puis une question : que faudrait-il vous montrer pour être convaincu ?"]},{"t":"Coaching","x":["Je ne vais pas te donner la solution aujourd’hui, je vais te poser trois questions.","Qu’est-ce que tu veux vraiment ? Qu’est-ce qui t’en empêche ? Qu’est-ce que tu pourrais faire dès demain ?","[Écoute. Silence de cinq secondes.]","Tu viens de dire quelque chose d’important : tu as déjà la réponse."]},{"t":"Présentation","x":["Je vais être bref, ensuite c’est vous qui parlez.","Notre projet : un menu numérique pour restaurants, installé en une journée.","Voici trois chiffres, puis un exemple.","Avant d’aller plus loin : quelle question vous vient en premier ?"]},{"t":"Appel de suivi","x":["Bonjour, je vous appelle pour savoir comment cela se passe depuis trois semaines.","Qu’est-ce qui marche bien ? Qu’est-ce qui vous agace encore ?","[Écoute, note.] Merci. Je corrige ce point cette semaine.","Je vous rappelle jeudi pour vous dire ce qui a changé."]}],"prix":[{"t":"Formation à la prise de parole · 30 s","x":["Le programme coûte quatre cents euros. [Silence de trois secondes.]","Il comprend quatre séances, un enregistrement à réécouter et un mois de suivi par message.","Voulez-vous commencer lundi prochain ?"],"d":30},{"t":"Formation à la prise de parole · 1 min","x":["Mon programme coûte quatre cents euros. [Silence de trois secondes.]","Voici ce qu’il comprend : quatre séances d’une heure, un texte prêt à lire pour chacune, un enregistrement à réécouter et un mois de suivi par message.","[Pause.]","Pour vous, cela représente moins de cent euros par semaine.","Les personnes qui le suivent jusqu’au bout doublent en général leur temps de parole sans notes.","Je vous propose de commencer lundi prochain avec une séance d’essai. Cela vous convient ?"],"d":60},{"t":"Formation à la prise de parole · 2 min","x":["Je vais vous donner le prix tout de suite, parce que vous avez le droit de savoir : le programme coûte quatre cents euros. [Silence de trois secondes.]","Voici ce qu’il comprend. Quatre séances d’une heure, une par semaine. Pour chaque séance, un texte prêt à lire, un exercice court et un retour précis. Un enregistrement de chaque séance, que vous pouvez réécouter. Et un mois de suivi par message, avec une réponse sous vingt-quatre heures.","[Pause.]","Si je ramène cela à une semaine, c’est moins de cent euros. Si je le ramène à une heure d’entraînement, c’est cent euros l’heure, avec quelqu’un qui vous écoute vraiment.","Maintenant, ce que ce prix n’inclut pas : il n’inclut pas de promesse magique. Le résultat dépend de votre régularité. Mais les personnes qui font les dix minutes par jour doublent en général leur temps de parole sans notes.","[Pause.]","Si ce prix vous convient, je vous propose de commencer lundi prochain avec une séance d’essai : si elle ne vous convient pas, vous ne payez pas la suite.","Et si le paiement en une fois vous gêne, nous pouvons le faire en trois fois.","Qu’est-ce qui vous semble le plus utile dans cette offre ?"],"d":120},{"t":"Site web pour un restaurant · 30 s","x":["Le site est à six cents euros, livré en deux semaines. [Silence.]","Il comprend le menu en ligne, les horaires et un bouton de réservation.","Nous commençons cette semaine ?"],"d":30},{"t":"Site web pour un restaurant · 1 min","x":["Le site est à six cents euros, livré en deux semaines. [Silence.]","Il comprend cinq pages : le menu, les horaires, la carte, les photos et un bouton pour réserver.","[Pause.]","Pendant le premier mois, les modifications sont gratuites.","Un autre restaurant qui a fait la même chose a reçu dix réservations de plus par semaine.","Nous commençons par le menu ou par les photos ?"],"d":60},{"t":"Site web pour un restaurant · 2 min","x":["Le site est à six cents euros, livré en deux semaines. [Silence de trois secondes.]","Voici ce que vous recevez, point par point. Cinq pages : l’accueil, le menu, la carte, les photos et les horaires avec un bouton de réservation. Un design adapté à votre cuisine et à votre quartier. Un menu que vous pouvez modifier vous-même en deux minutes. Un mois de modifications gratuites après la livraison.","[Pause.]","Pour vous situer : six cents euros, c’est environ le prix de deux services complets de samedi soir. Un restaurant comparable à Lognes a reçu dix réservations de plus par semaine après avoir mis son site en ligne, et deux fois moins d’appels pour demander les horaires.","[Pause.]","Je ne vous promets pas ces chiffres. Je vous promets que le site sera prêt à la date, et que vous pourrez le montrer à vos clients sans honte.","Si le budget est un sujet, nous pouvons commencer par trois pages, à quatre cents euros, et ajouter le reste plus tard.","Quelle option vous convient le mieux : le site complet ou la version à trois pages ?"],"d":120},{"t":"Application de gestion · 30 s","x":["L’application est à quatre-vingt-dix euros par mois, sans engagement. [Silence.]","Elle fait gagner en moyenne quatre heures par mois.","Vous pouvez l’arrêter quand vous voulez. On commence par un mois d’essai ?"],"d":30},{"t":"Application de gestion · 1 min","x":["L’application est à quatre-vingt-dix euros par mois, sans engagement. [Silence.]","Elle comprend la saisie des ventes, le suivi du stock et l’envoi des factures en un clic.","[Pause.]","En moyenne, elle fait gagner quatre heures par mois, soit environ deux cents euros de temps pour un indépendant.","Vous pouvez l’arrêter quand vous voulez, c’est la règle.","On commence par un mois d’essai, et je vous accompagne la première semaine ?"],"d":60},{"t":"Application de gestion · 2 min","x":["L’application est à quatre-vingt-dix euros par mois, sans engagement. [Silence de trois secondes.]","Voici ce qu’elle comprend : un carnet de ventes, un suivi de stock qui se met à jour tout seul, des factures qui partent en un clic, et un tableau de bord qui vous montre le chiffre du mois.","[Pause.]","Voyons ce que cela change. Vous m’avez dit passer deux heures chaque vendredi sur la facturation. Avec l’application, c’est vingt minutes. Cela fait environ six heures gagnées par mois. À cinquante euros l’heure, cela fait trois cents euros de temps, pour quatre-vingt-dix euros d’abonnement.","[Pause.]","Je vous dis aussi ce qu’elle ne fait pas : elle ne remplace pas votre comptable, et elle ne gère pas la paie.","Elle est sans engagement, vous pouvez l’arrêter quand vous voulez, et vous récupérez vos données dans un fichier.","Je vous propose un mois d’essai, avec un accompagnement la première semaine. Cela vous va ?"],"d":120},{"t":"Prix d’une formation","x":["« La formation coûte 150 000 ariary. » Silence de trois secondes.","« Elle comprend quatre semaines, un suivi et un enregistrement. »","« Souhaitez-vous commencer lundi ? »"]},{"t":"Prix d’un site","x":["« Le site est à 600 euros. » Silence.","« Il comprend cinq pages et un mois de maintenance. »","« On commence cette semaine ? »"]},{"t":"Prix d’un accompagnement","x":["« L’accompagnement est à 90 euros la séance. » Silence.","« Trois séances suffisent en général. »","« Quelle date vous convient ? »"]},{"t":"Prix d’une application","x":["« Une application sur mesure, à partir de 1 500 euros. » Silence.","« Elle est livrée en trois semaines. »","« Voulez-vous voir une démonstration ? »"]},{"t":"Prix d’un atelier","x":["« L’atelier est à 40 euros par personne. » Silence.","« Il dure deux heures, avec un support. »","« Combien serez-vous ? »"]},{"t":"Prix d’un cours","x":["« Le cours est à 25 000 ariary la séance. » Silence.","« Il comprend les exercices et un suivi par message. »","« Quand voulez-vous commencer ? »"]},{"t":"Prix d’un pack","x":["« Le pack complet est à 300 euros. » Silence.","« Il inclut les trois modules. »","« Quel module vous intéresse d’abord ? »"]},{"t":"Prix d’une prestation photo","x":["« La séance photo est à 120 euros. » Silence.","« Vous recevez vingt photos retouchées. »","« Quel jour vous convient ? »"]},{"t":"Prix d’un abonnement","x":["« L’abonnement est à 9 euros par mois. » Silence.","« Vous pouvez l’arrêter quand vous voulez. »","« Voulez-vous l’essayer ? »"]},{"t":"Prix d’une consultation","x":["« La consultation est à 60 euros. » Silence.","« Elle dure quarante-cinq minutes, avec un compte rendu écrit. »","« On la planifie ? »"]}],"analogie":[{"t":"Expliquer le budget","x":["Comme un réservoir : on y met de l’essence, on sait combien on a avant de partir.","Sans jauge, on tombe en panne au pire moment.","Donc un budget, c’est la jauge de votre argent."]},{"t":"Expliquer l’épargne","x":["Comme planter un arbre : petite graine aujourd’hui, ombre dans dix ans.","On ne voit rien pendant des mois, puis tout pousse.","L’épargne, c’est un arbre que l’on plante pour soi."]},{"t":"Expliquer une marque","x":["Comme un visage : on la reconnaît de loin et on se fie à son expression.","Si le visage change toute la journée, on ne sait plus à qui parler.","Une marque, c’est un visage qui reste le même."]},{"t":"Expliquer l’inflation","x":["Comme un ballon qu’on gonfle : le même billet remplit de moins en moins le panier.","Chaque année, le panier coûte un peu plus.","L’inflation, c’est le prix qui monte pendant que le salaire dort."]},{"t":"Expliquer l’épargne","x":["Comme un arbre : on plante petit, on attend, et l’ombre arrive plus tard.","Chaque pièce mise de côté est une feuille de plus.","L’épargne est l’ombre de demain."]},{"t":"Expliquer un contrat","x":["Comme une carte routière : elle ne conduit pas, mais elle évite de se perdre.","Les deux parties savent où elles vont.","Un contrat, c’est la carte avant le voyage."]},{"t":"Expliquer la confiance","x":["Comme un pont : chaque planche posée la rend plus solide.","Un seul faux pas peut l’ébranler.","La confiance se construit planche par planche."]},{"t":"Expliquer la régularité","x":["Comme une goutte d’eau sur la pierre : faible, mais constante.","Avec le temps, elle creuse.","La régularité fait ce que la force ne peut pas."]},{"t":"Expliquer le feedback","x":["Comme un miroir : on ne se voit pas soi-même.","Un bon retour montre ce qu’on ne peut pas voir.","Le feedback, c’est un miroir qui parle."]},{"t":"Expliquer l’écoute","x":["Comme un jardinier : il observe avant d’arroser.","S’il arrose trop vite, il noie.","Écouter, c’est regarder avant d’agir."]}],"positionnement":[{"t":"Coach de prise de parole","x":["J’aide les étudiants et les jeunes professionnels timides à parler avec clarté.","Je leur apprends une méthode simple pour parler sans notes.","Exercices courts, textes prêts à lire, suivi chaque semaine.","En dix minutes par jour, ils osent enfin prendre la parole."]},{"t":"Créateur d’applications","x":["Je crée des applications sur mesure pour des petites entreprises.","Ce que je fais : transformer un classeur Excel confus en un outil simple, qu’on utilise du premier jour.","Ce qui me différencie : je l’écris avec vous, pas à votre place.","Résultat : moins d’erreurs, plus de temps, et un outil qui vous ressemble."]},{"t":"Spécialiste du luxe","x":["J’étudie le luxe pour comprendre pourquoi un objet devient désirable.","Je sais lire une marque : son histoire, sa rareté, sa promesse.","Je mets cette lecture au service de marques qui veulent soigner leur image.","Mon objectif : que chaque détail raconte la même histoire."]},{"t":"Formateur en IA","x":["J’apprends aux équipes à utiliser l’intelligence artificielle sans se perdre.","Pas de jargon : des cas concrets, des consignes simples, des erreurs à éviter.","Mes élèves gagnent plusieurs heures par semaine.","Mon rôle : qu’ils restent aux commandes, et que l’outil travaille pour eux."]},{"t":"Photographe discret","x":["Je photographie les gens sans les déranger.","Mon style : la lumière naturelle, les silhouettes, l’instant juste avant.","On ne me remarque pas, et pourtant l’image dit tout.","Mon portrait, c’est celui où vous êtes vous-même, sans pose."]},{"t":"Formateur d’anglais","x":["J’aide les adultes à parler anglais sans avoir peur de se tromper.","Chaque séance, on parle : pas de grammaire en tableau noir.","Mes élèves osent leur première conversation en trois semaines.","Je leur donne une phrase, une situation, et du courage."]},{"t":"Chef de projet IT","x":["Je pilote des projets informatiques pour qu’ils sortent à l’heure et dans le budget.","Mon métier : traduire entre ceux qui rêvent et ceux qui codent.","Je réduis les surprises : un point par semaine, un tableau clair.","Résultat : une équipe qui sait où elle va."]},{"t":"Créateur de contenu","x":["Je crée du contenu qui donne envie d’en savoir plus, sans bruit inutile.","Un message clair, une image soignée, un rythme régulier.","Je raconte des vraies histoires, pas des slogans.","Mon contenu ne crie pas : il reste en tête."]},{"t":"Conférencier étudiant","x":["Je parle aux étudiants de ce que j’ai appris en le vivant.","Pas de théorie en l’air : des histoires, des erreurs, des astuces.","Je laisse la salle parler autant que moi.","Mon but : qu’ils sortent avec une idée qu’ils utilisent dès demain."]},{"t":"Entrepreneur à Madagascar","x":["Je construis ici ce que le monde attend de nous.","Des outils numériques, des emplois, des idées nées sur place.","Je pars de ce que je connais : ma terre, mes gens, mes besoins.","Ancré localement, ambitieux globalement."]}],"story":[{"t":"Le déclic","x":["Je parlais peu, j’évitais les micros.","À vingt ans, on m’a demandé de présenter devant l’école.","Mes mains tremblaient, j’ai commencé par une phrase préparée.","J’ai compris que la voix s’entraîne, comme un muscle."]},{"t":"L’arrivée en France","x":["Je vivais à Madagascar, entouré des miens.","Une opportunité d’études à Paris.","J’ai quitté mon pays avec un sac et un projet.","Je construis ici ce que je veux construire là-bas."]},{"t":"Les premiers cours d’anglais","x":["Je parlais anglais en classe, pas en vrai.","Un ami m’a mis face à un étranger.","J’ai bafouillé, il a souri.","J’ai fondé un club pour que d’autres osent."]},{"t":"La première application","x":["Je notais tout sur papier.","Un budget perdu par oubli.","J’ai construit un petit outil en une nuit.","Cet outil est devenu une famille d’outils."]},{"t":"L’alternance","x":["Étudiant sans expérience.","Un entretien où j’ai dit « je veux apprendre ».","Un an de chef de projet.","Une équipe qui m’a fait confiance."]},{"t":"L’association","x":["Une idée entre amis.","Un premier événement avec dix personnes.","On a invité, affiché, recommencé.","Une association qui vit sans nous."]},{"t":"La photographie","x":["Je regardais les photos des autres.","Un téléphone, une rue, une lumière.","Je cadrais dans l’ombre.","Un style discret qui me ressemble."]},{"t":"Le livre","x":["Des notes éparses.","Un élève m’a demandé « où lire ça ? ».","Trois mois d’écriture le soir.","Un manuel que d’autres utilisent."]},{"t":"Un échec","x":["J’étais sûr de moi.","Un projet lancé sans test.","Trois mois pour rien.","Je teste petit avant de lancer grand."]},{"t":"Ma mère et la ferme","x":["Elle comptait les œufs à la main.","Un soir, elle m’a dit qu’elle perdait le fil.","J’ai écrit un logiciel pour elle.","Elle gère sa ferme sur téléphone."]}],"pitchsoi":[{"t":"Pitch de 30 secondes","x":["Je m’appelle Stephen, j’ai vingt-trois ans, je viens de Madagascar.","Je crée des outils numériques pour des petits commerces.","Mon dernier projet fait gagner quarante minutes par jour à une ferme.","Je cherche des clients qui perdent du temps, et je leur rends.","Si vous en connaissez un, présentez-nous."]},{"t":"Pitch pour un recruteur","x":["Je suis étudiant en marketing de luxe, et j’ai passé un an en gestion de projet IT.","J’ai livré trois projets dans les délais.","Je veux mettre cette rigueur au service d’une marque.","Je serais heureux de vous en parler plus longuement."]},{"t":"Pitch pour un client","x":["Je construis des applications simples pour des commerces.","Je commence toujours par comprendre votre quotidien.","Je livre en trois semaines, avec formation.","Voulez-vous voir ce que cela donnerait chez vous ?"]},{"t":"Pitch pour une école","x":["J’ai présidé une association de prise de parole pendant un an.","J’ai organisé des ateliers pour plus de cinquante élèves.","Je propose le même format ici, gratuitement.","Quand pouvons-nous nous voir ?"]},{"t":"Pitch pour un partenaire","x":["Je lance une plateforme de prise de parole.","Elle propose des leçons, des exercices et des textes prêts à lire.","Je cherche un partenaire pour la distribuer.","Pouvons-nous en discuter cette semaine ?"]},{"t":"Pitch pour une soirée","x":["Je suis Stephen, je viens d’arriver à Paris.","J’étudie le luxe et je crée des applications.","Ce qui m’anime : aider les gens à parler avec confiance.","Et vous, qu’est-ce qui vous anime ?"]},{"t":"Pitch pour un jury","x":["Mon projet répond à un problème simple : peu de gens apprennent à parler.","Ma solution : une application avec des textes à lire et des exercices.","Mes preuves : trente utilisateurs en test.","Je demande aujourd’hui vos retours."]},{"t":"Pitch pour un étudiant","x":["Je fais des applis pour m’entraîner à parler.","Dix minutes par jour, des textes déjà écrits.","Tu lis, tu t’enregistres, tu t’écoutes.","Essaie, c’est gratuit."]},{"t":"Pitch pour un investisseur","x":["Je construis une famille d’applications pour entrepreneurs malgaches.","Elles sont simples, mobiles, adaptées au réseau local.","Premiers usages : une ferme et un centre d’anglais.","Je cherche un premier soutien pour passer à l’échelle."]},{"t":"Pitch pour LinkedIn","x":["Étudiant, entrepreneur, créateur d’outils numériques.","Je construis des applications utiles aux petits commerces.","Ma conviction : on grandit quand on a le bon environnement.","Je suis ouvert aux échanges sur ces sujets."]}],"contenu":[{"t":"Post : régularité","x":["« Dix minutes par jour. »","La régularité bat l’intensité.","Un mois de lecture à voix haute, moins de « euh ».","« Et vous, quelle est votre dix minutes ? »"]},{"t":"Post : un premier voyage seul","x":["« J’avais peur de partir seul. »","On se découvre en se perdant un peu.","Un train raté, une rencontre, un souvenir pour la vie.","« Quel voyage remettez-vous à plus tard ? »"]},{"t":"Post : le dimanche sans écran","x":["« Dimanche, j’ai posé mon téléphone. »","On retrouve le temps quand on l’arrête de remplir.","Trois heures, un livre, une promenade, aucune notification.","« Et vous, quand avez-vous éteint pour la dernière fois ? »"]},{"t":"Post : une erreur","x":["« J’ai perdu trois mois. »","Tester avant de lancer.","Un projet sans test.","« Quel test ferez-vous cette semaine ? »"]},{"t":"Post : remercier","x":["« Merci n’est pas un mot facile. »","Un merci précis marque.","Remercier pour un geste daté.","« Qui allez-vous remercier ? »"]},{"t":"Post : conseil","x":["« Un seul conseil. »","S’enregistrer.","Trente secondes de voix chaque soir.","« Essayez ce soir. »"]},{"t":"Post : coulisses","x":["« Ce que personne ne voit. »","Le travail derrière le résultat.","Vingt versions d’une phrase.","« Que cachent vos résultats ? »"]},{"t":"Post : une citation vécue","x":["« On m’a dit : parle moins vite. »","La vitesse est un choix.","Une minute à la moitié du débit.","« Testez-le aujourd’hui. »"]},{"t":"Post : bilan du mois","x":["« Ce mois-ci, trois leçons. »","Apprendre à rendre compte.","Un point chaque vendredi.","« Quelle est votre leçon ? »"]},{"t":"Post : annonce","x":["« Ça y est. »","Un lancement simple.","Une application, un public, une date.","« Dites-moi ce que vous en pensez. »"]}],"express":[{"t":"Mon objet préféré","x":["Voici un objet que je garde toujours : mon carnet noir.","Il m’a vu écrire mes premiers discours.","Chaque page est un morceau de moi.","Si je le perds, je perds une partie de mon histoire.","Et vous, quel objet vous accompagne ?"]},{"t":"Un lieu qui m’a marqué","x":["Un lieu m’a marqué : la gare de Lognes, tôt le matin.","On y croise des gens fatigués, mais jamais indifférents.","Chaque jour, j’y réfléchis à ma journée.","Ce lieu m’apprend la patience.","Quel lieu vous apprend quelque chose ?"]},{"t":"Une personne qui m’inspire","x":["Une personne m’inspire : ma mère.","Elle gère une ferme avec cinq fois moins de moyens que d’autres.","Elle ne se plaint pas, elle compte, elle ajuste.","Elle m’a appris la constance.","Qui vous a appris quelque chose sans le dire ?"]},{"t":"Mon plus grand apprentissage","x":["Mon plus grand apprentissage : demander.","Longtemps, j’ai attendu qu’on devine mes besoins.","Un jour, j’ai posé une question simple, et tout a changé.","Demander n’est pas faible, c’est efficace.","Que devriez-vous demander ?"]},{"t":"Ce que je ferais avec un million","x":["Avec un million, je construirais un centre de formation.","Pas un bâtiment spectaculaire, un lieu simple.","On y apprendrait à parler et à créer.","Le reste viendrait par les gens.","Et vous, que feriez-vous ?"]},{"t":"Mon matin idéal","x":["Mon matin idéal commence à cinq heures.","Un verre d’eau, dix minutes de lecture à voix haute.","Puis une marche, sans téléphone.","À huit heures, j’ai déjà vécu une journée.","Quel est le vôtre ?"]},{"t":"Un conseil à mon moi plus jeune","x":["Je dirais à mon moi plus jeune : ose.","Ose parler, ose demander, ose recommencer.","Les erreurs d’aujourd’hui sont les leçons de demain.","Tu auras peur, mais tu iras.","Quel conseil donneriez-vous ?"]},{"t":"Une idée qui me tient à cœur","x":["Une idée me tient à cœur : que chacun sache parler.","Pas pour briller, pour être entendu.","Un mot juste peut changer une vie.","C’est pour cela que je construis tout cela.","Quelle idée vous porte ?"]},{"t":"Ce que j’ai appris cette semaine","x":["Cette semaine, j’ai appris à dire non.","Trois fois, avec un sourire.","Mon agenda a respiré.","Je livre mieux ce que je garde.","Qu’avez-vous appris cette semaine ?"]},{"t":"Un souvenir d’enfance","x":["Un souvenir d’enfance : le dimanche chez ma grand-mère.","L’odeur du riz, le bruit de la casserole.","Personne ne parlait fort, tout le monde se comprenait.","Ce souvenir est ma référence de douceur.","Quel est le vôtre ?"]}],"fetiche":[{"t":"Mon mot fétiche : régulier","x":["Régulier : un mot que j’aime répéter.","Être régulier, c’est tenir quand l’élan s’en va.","Il ne brille pas, il construit.","Chaque matin, c’est mon mot d’ordre.","Et le vôtre ?"]},{"t":"Mon mot fétiche : clair","x":["Clair : un mot qui fait du bien.","Parler clair, c’est respecter celui qui écoute.","Une phrase claire est une phrase qui sert.","Je cherche cette clarté dans tout ce que je dis.","Et vous ?"]},{"t":"Mon mot fétiche : promesse","x":["Promesse : un mot lourd.","Promettre, c’est engager sa parole.","Je promets peu, mais je tiens.","Une promesse tenue vaut dix intentions.","Quelle promesse tenez-vous ?"]},{"t":"Mon mot fétiche : lenteur","x":["Lenteur : un mot qu’on évite.","Pourtant, la lenteur permet de voir.","Je ralentis pour parler juste.","La lenteur est une force discrète.","Et vous, ralentissez-vous ?"]},{"t":"Mon mot fétiche : ensemble","x":["Ensemble : un mot court, un monde large.","Seul, j’avance, ensemble, je construis.","Mon projet n’existe pas sans les autres.","Ensemble, c’est ma façon de grandir.","Avec qui avancez-vous ?"]},{"t":"Mon mot fétiche : question","x":["Question : un mot qui ouvre.","Une bonne question vaut mieux qu’une réponse.","Elle fait réfléchir celui qui l’écoute.","Je pose une question avant d’avoir un avis.","Quelle question vous habite ?"]},{"t":"Mon mot fétiche : racine","x":["Racine : un mot qui ancre.","Mes racines sont à Madagascar.","Elles me donnent la direction, pas la limite.","Je grandis vers le haut parce que je suis enraciné.","Où sont les vôtres ?"]},{"t":"Mon mot fétiche : essai","x":["Essai : un mot qui libère.","Un essai n’est pas un échec.","C’est une porte ouverte.","J’essaie tous les jours quelque chose de petit.","Qu’essayez-vous ?"]},{"t":"Mon mot fétiche : écoute","x":["Écoute : un mot qu’on sous-estime.","Écouter, c’est donner du temps.","J’écoute avant de répondre, toujours.","C’est la meilleure façon de comprendre.","Qui avez-vous écouté aujourd’hui ?"]},{"t":"Mon mot fétiche : départ","x":["Départ : un mot qui fait peur et qui fait envie.","Chaque départ est un risque et un cadeau.","J’en ai fait deux grands, et plusieurs petits.","Je ne regrette que ceux que je n’ai pas faits.","Quel départ préparez-vous ?"]}],"faury":[{"t":"Prendre la parole, prendre le temps","x":["[Debout. Respirez. Regardez le fond de la salle.]","On dit qu’il faut prendre la parole.","[Pause.]","Moi, je trouve qu’on la prend toujours un peu trop vite.","On l’attrape comme un bus qui démarre,","on court, on s’accroche,","et on arrive essoufflé devant des gens qui attendaient autre chose.","[Pause.]","Alors cette fois, je propose l’inverse.","Prendre le temps.","[Pause.]","Prendre le temps de poser le sac,","de poser la voix,","de poser la question avant de poser la réponse.","[Pause.]","Parce que la parole, ce n’est pas une course.","C’est une marche.","Et dans une marche,","ce qui compte, ce n’est pas la vitesse :","c’est le pas qu’on pose, puis celui qu’on ose.","[Souriez. Laissez le jeu de sons passer.]","Poser, oser.","Un seul mot de différence,","et pourtant tout un monde entre les deux.","[Pause.]","Poser, c’est être là.","Oser, c’est être là quand ça tremble.","[Pause.]","J’ai appris ça un matin d’hiver,","dans une salle de classe trop chauffée,","devant vingt visages qui me regardaient comme on regarde un four à pain :","avec espoir, et sans aucune idée de ce qui allait en sortir.","[Laissez rire.]","J’ai ouvert la bouche.","Rien n’est venu.","[Pause. Silence de 3 secondes.]","Et dans ce silence,","quelqu’un a toussé,","quelqu’un a souri,","et j’ai compris que personne ne me jugeait :","on m’attendait.","[Pause.]","Voilà.","Attendre,","ce n’est pas juger.","C’est donner du temps.","[Ralentissez.]","Alors si vous devez prendre la parole un jour,","ne la prenez pas comme on prend un train en marche.","Prenez-la comme on prend une main :","doucement,","en regardant la personne,","en sachant qu’on ne la serre pas pour la garder,","mais pour l’accompagner.","[Pause longue.]","Prendre la parole.","Prendre le temps.","[Voix posée.]","C’est presque la même chose.","[Silence final de 3 secondes.]"]},{"t":"Le silence a la parole","x":["[Regardez la salle. Silence de 3 secondes avant de commencer.]","Vous avez remarqué ?","[Pause.]","Depuis que je suis monté sur cette scène,","j’ai déjà dit sept phrases,","et la plus forte, c’est celle que je n’ai pas dite.","[Pause.]","Le silence.","Il a mauvaise réputation.","On dit « un silence gêné »,","« un silence pesant »,","« un silence de mort ».","Personne ne dit jamais :","« un silence qui sait ce qu’il dit ».","[Pause.]","Et pourtant.","[Ralentissez.]","Sous les sapins de mon enfance,","il y avait un silence qui sentait la sève et la neige fraîche,","un silence si net qu’on entendait le sac de sucre se fendre dans l’armoire.","[Pause.]","Ce silence-là ne manquait de rien.","Il était plein,","plein comme une soupe de grand-mère le dimanche.","[Laissez rire.]","Alors pourquoi, dès qu’on parle en public,","a-t-on peur qu’il se glisse entre deux phrases ?","[Pause.]","Parce qu’on croit qu’un blanc,","c’est un trou.","Or un blanc,","c’est une respiration.","[Pause.]","Un orateur qui se tait deux secondes,","ce n’est pas un orateur qui a perdu ses mots.","[Voix plus basse.]","C’est un orateur qui les laisse arriver.","[Pause longue.]","On dit que la parole est d’argent et le silence d’or.","Je crois plutôt ceci :","la parole est faite pour dire,","et le silence pour que ce qu’on a dit","ait le temps de devenir vrai.","[Pause.]","Alors la prochaine fois que le silence vous guette,","ne le chassez pas.","Offrez-lui un fauteuil.","[Souriez.]","Il a beaucoup de choses à vous dire.","[Silence final de 4 secondes. Ne remplissez pas.]"]},{"t":"Une promesse ne se rend pas","x":["[Regardez deux personnes différentes. Voix chaleureuse.]","On dit que les promesses n’engagent que ceux qui y croient.","[Pause.]","Je voudrais dire l’inverse.","Les promesses engagent surtout ceux qui les entendent.","[Pause.]","Parce que celui qui promet,","lui, a l’air de donner.","Mais celui qui écoute,","lui, se met à attendre.","[Pause.]","Et attendre,","c’est déjà un peu de la confiance.","[Ralentissez.]","Quand j’avais neuf ans,","mon père m’a promis un vélo.","Pas un vélo neuf.","Un vélo qui avait connu trois étés et deux chutes,","avec un guidon un peu tordu,","comme s’il voulait toujours tourner à gauche.","[Laissez rire.]","Il m’a dit :","« Quand tu auras appris à lire l’heure, je te le donne. »","[Pause.]","J’ai appris l’heure en quinze jours.","Les aiguilles,","les chiffres,","le grand,","le petit,","le quart,","et la demie.","[Pause.]","Le vélo est arrivé trois mois plus tard.","[Silence de 2 secondes.]","Trois mois.","Et pourtant,","je n’ai jamais pensé qu’il avait manqué à sa parole.","[Pause.]","Parce que pendant ces trois mois,","j’ai appris autre chose :","qu’il y a des gens dont on attend la parole","comme on attend le printemps,","sans douter qu’il vienne.","[Pause.]","Aujourd’hui, je n’ai plus le vélo.","Il a rouillé sous un hangar quelque part.","Mais j’ai gardé la promesse.","Et quand je parle,","je me demande toujours si ce que je dis","pourrait être attendu trois mois","par quelqu’un qui m’a cru.","[Pause longue.]","Une promesse ne se rend pas.","[Voix simple.]","Elle se tient.","[Silence final de 3 secondes.]"]},{"t":"La peur est un public","x":["[Respirez. Souriez dès la première phrase.]","Il paraît que la peur de parler en public","fait plus peur que la mort.","[Pause.]","Je ne sais pas si c’est vrai.","Mais ce que je sais,","c’est que la mort,","au moins,","ne vous demande pas de faire un exposé.","[Laissez rire.]","Alors parlons de cette peur.","Pas pour la chasser.","Pour la regarder.","[Pause.]","Ma peur,","elle a des habitudes.","Elle arrive toujours cinq minutes avant moi.","Elle s’installe au premier rang.","Elle croise les bras.","Et elle me regarde comme un examinateur sans pitié.","[Pause.]","Un jour,","je me suis demandé :","et si ce n’était pas un examinateur ?","Et si c’était simplement","un public ?","[Pause.]","Un public,","ça écoute.","Un public,","ça attend.","Un public,","ça espère,","parfois même plus que vous.","[Ralentissez. Silence de 2 secondes.]","Alors j’ai changé de méthode.","Au lieu de la fuir,","je lui ai donné une place.","Au premier rang,","bien sûr.","Elle a l’habitude.","[Pause.]","Et à chaque prise de parole,","je lui dis :","« Écoute-moi.","Si ce que je dis ne vaut rien,","tu auras raison de trembler.","Mais si ça vaut quelque chose,","alors tu trembles pour la bonne raison. »","[Pause.]","Voilà ce qu’elle m’a appris.","Que trembler,","ce n’est pas échouer.","[Voix plus basse.]","C’est tenir à quelque chose.","[Pause.]","Alors la prochaine fois que votre peur s’assoit au premier rang,","ne lui demandez pas de partir.","Demandez-lui de rester.","[Souriez.]","Elle a plus de choses à vous apprendre qu’aucun professeur.","[Silence final de 3 secondes. Regardez quelqu’un.]"]}]};})();
